import sys
import math

def manhattan_dist(p1, p2):
    """Calculate the Manhattan distance between two points."""
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

def find(x):
    """Find the root of a set with path compression."""
    if x != parent[x]:
        parent[x] = find(parent[x])
    return parent[x]

def union(x, y):
    """Union two sets with union by rank."""
    rootX = find(x)
    rootY = find(y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def find_minimized_max_edge(n, coordinates):
    """Find the minimum spanning tree with minimized maximum edge weight."""
    parent = list(range(n))
    rank = [0] * n
    edges = sorted([(manhattan_dist(coordinates[i], coordinates[j]), i, j) for i in range(n) for j in range(i + 1, n)])
    min_max_weight = sys.maxsize
    for _, u, v in edges:
        if find(u) != find(v):
            union(u, v)
            max_weight = max(manhattan_dist(coordinates[u], coordinates[v]), max(manhattan_dist(coordinates[u], coordinates[i]), manhattan_dist(coordinates[i], coordinates[v])) for i in range(n) if find(u) == find(i) and find(v) == find(i))
            min_max_weight = min(min_max_weight, max_weight)
    return min_max_weight

