def gcd(a, b):
    """Calculate the greatest common divisor of two numbers."""
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    """Calculate the least common multiple of two numbers."""
    return a * b // gcd(a, b)

def smallest_common_multiple(a, b, c, x):
    """
    Determine the smallest common multiple of three numbers a, b, c greater than x.
    """
    # Calculate the least common multiple of a and b
    lcm_ab = lcm(a, b)

    # Check if lcm_ab > x
    if lcm_ab >= x:
        # Calculate the least common multiple of lcm_ab and c
        return lcm(lcm_ab, c)
    else:
        # If lcm_ab is not greater than x, calculate lcm_ab * (c + x - 1) / (c + 1)
        return lcm_ab * (c + x - 1) // (c + 1)

