from collections import defaultdict, deque

def count_paths(n, m, edges, queries):
    # Build the adjacency list for the graph
    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)

    # Initialize the answer dictionary
    answer = {query: 0 for query in queries}

    # For each query, calculate the paths using BFS
    for u, v in queries:
        queue = deque([(u, 1)])
        visited = set([u])

        while queue:
            current, count = queue.popleft()
            if current == v:
                answer[(u, v)] = count
                continue

            for neighbor in graph[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, count + 1))

        # If no path is found, set the answer to 0
        if answer[(u, v)] == 0:
            answer[(u, v)] = 0

    # Print the answer for each query
    for query in queries:
        print(answer[query])
```

This Python solution constructs a graph from the input data and uses Breadth-First Search (BFS) to count the number of distinct paths from vertex `u` to vertex `v` for each query pair. It utilizes a queue to maintain the current path and a set to track visited vertices to avoid cycles.

