def max_robbery(n: int, money: List[int]) -> int:
    if n == 0:
        return 0
    elif n == 1:
        return money[0]
    elif n == 2:
        return max(money[0], money[1])

    rob1, rob2 = money[0], max(money[0], money[1])
    for i in range(2, n):
        next_rob = max(rob1 + money[i], rob2)
        rob1, rob2 = rob2, next_rob

    return rob2
