def limit_event_frequency(events, N):
    # Initialize a dictionary to keep track of event counts
    event_counts = {}
    for event in events:
        if event in event_counts:
            event_counts[event] += 1
        else:
            event_counts[event] = 1
        # Ensure each event appears at most N times
        if event_counts[event] > N:
            event_counts.pop(event)

    # Create a new list with events that appear at most N times
    result = []
    for event in events:
        if event in event_counts and event_counts[event] <= N:
            result.append(event)
            event_counts[event] -= 1

    return result
```

