def is_strongly_connected(n, m, edges):
    # Build the graph from the given edges
    graph = defaultdict(list)
    for u, v in edges:
        graph[u-1].append(v-1)

    # Initialize the visited set
    visited = set()

    # Check each section
    for i in range(n):
        if i not in visited:
            if not dfs(graph, i, visited):
