from collections import defaultdict

def enrollments_to_dict(enrollments):
    """
    Converts a list of enrollment records into a dictionary where the keys are course IDs and the values
    are lists of sorted student IDs enrolled in these courses.

    :param enrollments: List of tuples, where each tuple contains a student ID and a course ID.
    :return: Dictionary where keys are course IDs and values are sorted lists of student IDs.
    """
    # Dictionary to hold the course IDs and their corresponding sorted student IDs
    course_enrollments = defaultdict(list)

    # Iterate over each enrollment record
    for student_id, course_id in enrollments:
        course_enrollments[course_id].append(student_id)

    # Sort each list of student IDs for the course
    for course_id, students in course_enrollments.items():
        course_enrollments[course_id] = sorted(students)

    return dict(course_enrollments)

