from typing import List

def maximize_sum(n: int, k: int, sequence: List[int]) -> int:
    # If we can perform all operations on the positive numbers, we can maximize the sum
    if k >= n:
        return sum(sequence)

    # Sort the sequence in descending order
    sequence.sort(reverse=True)

    # Subtract the largest elements until we have completed k operations
    for _ in range(k):
        sequence.pop(0)

    # The sum of the remaining elements is the maximum possible sum after k operations
    return sum(sequence)

