def find_median(arr: List[int]) -> int:
    def partition(arr, low, high):
        pivot = arr[high]
        i = low - 1
        for j in range(low, high):
            if arr[j] <= pivot:
                i += 1
                arr[i], arr[j] = arr[j], arr[i]
        arr[i + 1], arr[high] = arr[high], arr[i + 1]
        return i + 1

    def quick_select(arr, low, high, k):
        if low == high:
            return arr[low]
        pi = partition(arr, low, high)
        if k == pi:
            return arr[k]
        elif k < pi:
            return quick_select(arr, low, pi - 1, k)
        else:
            return quick_select(arr, pi + 1, high, k)

    n = len(arr)
    if n % 2 == 0:
        return (quick_select(arr, 0, n - 1, n // 2 - 1) + quick_select(arr, 0, n - 1, n // 2)) / 2
    else:
        return quick_select(arr, 0, n - 1, n // 2)
```
This Python function implements the Quick Select algorithm to find the median of an array without using any in-built sort functions. It first partitions the array into two parts using the Quick Sort pivot selection method and then recursively selects the k-th smallest element. The median is found by taking the k-th smallest element if n is even, or the average of the k-th and (k+1)-th smallest elements if n is odd.

