from collections import deque

class AvlNode:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None
        self.height = 1

class AVLWithKthElement(AvlTree):
    def __init__(self):
        super().__init__()

    def _height(self, root):
        if not root:
            return 0
        return root.height

    def _get_balance(self, root):
        if not root:
            return 0
        return self._height(root.left) - self._height(root.right)

    def _rotate_left(self, root):
        y = root.right
        T2 = y.left

        y.left = root
        root.right = T2

        root.height = 1 + max(self._height(root.left),
                              self._height(root.right))
        y.height = 1 + max(self._height(y.left),
                            self._height(y.right))

        return y

    def _rotate_right(self, root):
        x = root.left
        T3 = x.right

        x.right = root
        root.left = T3

        root.height = 1 + max(self._height(root.left),
                              self._height(root.right))
        x.height = 1 + max(self._height(x.left),
                            self._height(x.right))

        return x

    def _get_balance_factor(self, root):
        if not root:
            return 0
        return self._height(root.left) - self._height(root.right)

    def _get_kth_smallest_helper(self, root, k, low, high):
        while low <= high:
            pivot = low + (high - low) // 2

            if k == pivot:
                return self._get_kth_smallest_helper(root, k, pivot + 1, high)
            elif k < pivot:
                high = pivot - 1
            else:
                low = pivot + 1

            if low <= high:
                return self._get_kth_smallest_helper(root, k, low, high)

        return root.key

    def find_kth_smallest(self, k):
        if not self.root:
            raise ValueError("Tree is empty")

        return self._get_kth_smallest_helper(self.root, k, 0, len(self) - 1)
```

