from collections import deque

class MaxMinHeap:
    def __init__(self):
        self.max_heap = []
        self.min_heap = []

    def insert(self, x):
        # Insert into max-heap
        heapq.heappush(self.max_heap, (-x, x))
        # Insert into min-heap
        heapq.heappush(self.min_heap, x)

    def remove(self, x):
        # Remove from max-heap
        if self.max_heap and (-self.max_heap[0][1] == x):
            heapq.heappop(self.max_heap)
        # Remove from min-heap
        if self.min_heap and self.min_heap[0] == x:
            heapq.heappop(self.min_heap)

    def find_max(self):
        # Return the maximum value from the max-heap
        return -self.max_heap[0][1] if self.max_heap else None

class MaxMin:
