        self.heap = MaxMinHeap()
        self.numbers = set()

    def insert(self, x):
        if x in self.numbers:
            return
        self.heap.insert(x)
        self.numbers.add(x)

    def remove(self, x):
        self.heap.remove(x)
        self.numbers.remove(x)

    def find_max(self):
        return self.heap.find_max() if self.heap.max_heap else None

