```python
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class MaxBST:
    def __init__(self):
        self.root = None

    def insert(self, val):
        if not self.root:
            self.root = TreeNode(val)
        else:
            self._insert(val, self.root)

    def _insert(self, val, node):
        if val < node.val:
            if node.left:
                self._insert(val, node.left)
            else:
                node.left = TreeNode(val)
        else:
            if node.right:
                self._insert(val, node.right)
            else:
                node.right = TreeNode(val)

    def remove(self, val):
        self.root = self._remove(val, self.root)

    def _remove(self, val, node):
        if not node:
            return None

        if val < node.val:
            node.left = self._remove(val, node.left)
        elif val > node.val:
            node.right = self._remove(val, node.right)
        else:
            if not node.left:
                return node.right
            if not node.right:
                return node.left

            temp = node.right
            while temp.left:
                temp = temp.left
            node.val = temp.val
            node.right = self._remove(temp.val, node.right)

        return node

    def find_max(self):
        if not self.root:
            return "Empty"
        return self.root.val

