def contain_string_optimized(haystack: str, needle: str) -> int:
    if not needle:
        return 0  # Early exit if the needle is empty

    # Precompute the length of the needle and initialize the KMP table
    needle_length = len(needle)
    kmp_table = [0] * needle_length
    position = 0  # Position in the needle
    for i in range(1, needle_length):
        while position > 0 and needle[i] != needle[position]:
            position = kmp_table[position - 1]  # Backtrack
        if needle[i] == needle[position]:
            position += 1
        kmp_table[i] = position

    # Initialize variables
    position_in_haystack = 0
    position_in_needle = 0

    # Search for the needle in the haystack
    while position_in_haystack < len(haystack) and position_in_needle < needle_length:
        if haystack[position_in_haystack] == needle[position_in_needle]:
            position_in_needle += 1
        else:
            position_in_haystack -= position_in_needle  # Move to previous character if mismatch
            position_in_needle = 0  # Reset position in needle

        if position_in_needle == needle_length:
            return position_in_haystack - (needle_length - 1)  # Return the position in haystack

    return -1  # Needle not found
