import heapq
from collections import defaultdict
from typing import List, Tuple

def find_min_travel_time(N: int, portals: List[Tuple[int, int, int]], queries: List[Tuple[int, int]]) -> List[int]:
    def dijkstra(start, end, portals):
        distances = defaultdict(lambda: float('inf'))
        distances[start] = 0
        priority_queue = [(0, start)]

        while priority_queue:
            current_distance, current_node = heapq.heappop(priority_queue)

            if current_distance > distances[current_node]:
                continue

            for portal, cost in portals:
                if distances[portal] > current_distance + cost:
                    distances[portal] = current_distance + cost
                    heapq.heappush(priority_queue, (current_distance + cost, portal))

        return distances[end]

    results = []
    for query in queries:
        start, end = query
        result = dijkstra(start, end, portals)
        results.append(result if result != float('inf') else -1)

    return results

def solve_teleportation_queries(T: int, configurations: List[Tuple[int, int, int, List[Tuple[int, int, int]], List[Tuple[int, int]]]]) -> List[int]:
    def solve_case(t, config):
        N, M, W, portals, queries = config
        return find_min_travel_time(N, portals, queries)

    return [solve_case(t, config) for t in range(1, T+1)]
