def combination_optimized(n, r):
    # Base case: if n is less than r, return 0
    if n < r:
        return 0
    # If r is 0 or n is 0, return 1
    elif r == 0 or n == 0:
        return 1

    # If r is greater than n/2, use the symmetry property to compute the result
    if r > n // 2:
        r = n - r

    # Initialize the result array with the base case values
    result = [1] * (n + 1)

    # Compute the binomial coefficient using dynamic programming
    for i in range(2, r + 1):
        for j in range(min(i, r), 0, -1):
            result[j] = result[j] * (n - i + 1) // j

    # Return the result for the given r
    return result[r]
