from collections import deque

def shortest_path_on_hexagrid(n, m, edges, start, target):
    # Create a graph based on the edges
    graph = {}
    for edge in edges:
        x1, y1, z1, x2, y2, z2 = edge
        graph[(x1, y1, z1)] = [(x2, y2, z2), (x1, y1, z1)]

    # Helper function to find the shortest path
    def bfs(x1, y1, z1, x2, y2, z2):
        queue = deque([(x1, y1, z1, 0, [])])
        seen = {(x1, y1, z1)}
        while queue:
            x, y, z, dist, path = queue.popleft()
            if (x, y, z) == (x2, y2, z2):
                return dist, path
            for nx, ny, nz in ((x+1, y, z), (x, y+1, z), (x, y, z+1), (x+1, y+1, z+1), (x-1, y+1, z+1), (x+1, y-1, z+1)):
                if (nx, ny, nz) not in seen:
                    seen.add((nx, ny, nz))
                    graph[(nx, ny, nz)].append((x, y, z))
                    queue.append((nx, ny, nz, dist+1, path + [(x, y, z)]))
        return float('inf'), []

    # Calculate distances and paths for each pair of hexagons
    distances = {}
    paths = {}
    for hex1 in graph:
        for hex2 in graph:
            if hex1 != hex2:
                dist, path = bfs(*start, *hex1, *hex2)
                if dist != float('inf'):
                    distances[hex1] = dist
                    distances[hex2] = dist
                    paths[hex1] = path
                    paths[hex2] = path

    # Find the shortest path between start and target
    shortest_dist, shortest_path = bfs(*start, *target)
    shortest_path.reverse()
    return shortest_dist, shortest_path
```
