def is_perfect_number(n: int) -> bool:
    if n <= 1:
        return False

    # 1 is the only number that is its own perfect divisor.
    if n == 2:
        return True

    sum_of_divisors = 1  # 1 is always a divisor of any number
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            sum_of_divisors += i
            if i != n // i:  # Avoid adding the square root twice for perfect squares
                sum_of_divisors += n // i

    return sum_of_divisors == n
```
