from typing import List, Tuple

class ArrayProcessor:
    def spiral_order(self, array: List[List[int]]) -> List[int]:
        if not array or not array[0]:
            return []

        result = []
        top, bottom = 0, len(array) - 1
        left, right = 0, len(array[0]) - 1

        while top <= bottom and left <= right:
            # Traverse from left to right
            for col in range(left, right + 1):
                result.append(array[top][col])
            top += 1

            # Traverse from top to bottom
            for row in range(top, bottom + 1):
                result.append(array[row][right])
            right -= 1

            # Check if there are elements left to traverse
            if top <= bottom:
                # Traverse from right to left
                for col in range(right, left - 1, -1):
                    result.append(array[bottom][col])
                bottom -= 1

                # Traverse from bottom to top
                for row in range(bottom, top - 1, -1):
                    result.append(array[row][left])
                left += 1

        return result

    def rotate_90_clockwise(self, array: List[List[int]]) -> List[List[int]]:
        if not array or not array[0]:
            return []

        n = len(array)
        result = [[0] * n for _ in range(n)]

        for i in range(n):
            for j in range(n):
                result[j][n - 1 - i] = array[i][j]

        return result

    def transpose(self, array: List[List[int]]) -> List[List[int]]:
        if not array or not array[0]:
            return []

        n = len(array)
        result = [[0] * n for _ in range(n)]

        for i in range(n):
            for j in range(n):
                result[i][j] = array[j][i]

        return result

    def search_element(self, array: List[List[int]], element: int) -> Tuple[int, int]:
        for i in range(len(array)):
            for j in range(len(array[0])):
                if array[i][j] == element:
                    return (i, j)
        return (-1, -1)
