def max_subarray_sum(nums):
    def find_max_sum(nums, left, right):
        if left == right:
            return nums[left]

        mid = (left + right) // 2
        left_max = find_max_sum(nums, left, mid)
        right_max = find_max_sum(nums, mid + 1, right)
        cross_max = find_cross_sum(nums, left, mid, right)

        return max(left_max, right_max, cross_max)

    def find_cross_sum(nums, left, mid, right):
        left_sum = float('-inf')
        curr_sum = 0
        for i in range(mid, left - 1, -1):
            curr_sum += nums[i]
            left_sum = max(left_sum, curr_sum)

        right_sum = float('-inf')
        curr_sum = 0
        for i in range(mid + 1, right + 1):
            curr_sum += nums[i]
            right_sum = max(right_sum, curr_sum)

        return left_sum + right_sum

    return find_max_sum(nums, 0, len(nums) - 1)
