def max_sum_subgrid(N, M, grid):
    # Cache to store the maximum sum of subgrids already computed
    cache = {}

    def max_sum_subgrid_helper(start_row, end_row, start_col, end_col):
        if (start_row, start_col) in cache:
            return cache[(start_row, start_col)]

        if start_row > end_row or start_col > end_col:
            return 0

        max_sum = 0
        for i in range(start_col, end_col + 1):
            max_sum = max(max_sum, grid[start_row][i] + max_sum_subgrid_helper(start_row + 1, end_row, start_col + 1, end_col))

        cache[(start_row, start_col)] = max_sum
        return max_sum

    return max_sum_subgrid_helper(0, N - 1, 0, M)

