def is_palindrome_and_longest_substring(s):
    def prepare_string(s):
        """Prepare the string by removing non-alphanumeric characters and converting to lowercase."""
        return ''.join(filter(str.isalnum, s)).lower()

    def find_longest_palindromic_substring(s):
        """Find the longest palindromic substring using Manacher's algorithm."""
        if len(s) <= 1:
            return (True, s)
        n = len(s)
        p = [0] * n
        center, right, maxLength = 0, 0, 0
        for i in range(1, n - 1):
            mirror = 2 * center - i
            if i < right:
                p[i] = min(right - i, p[mirror])
            while s[i + (1 + p[i])] == s[i - (1 + p[i])]:
                p[i] += 1
            if i + p[i] > right:
                center, right = i, i + p[i]
        for i in range(maxLength):
            if s[i + (1 + p[i])] != s[i - (1 + p[i])]:
                break
        return (p[i] == maxLength, s[i - (1 + p[i]) : i + p[i]])

    s = prepare_string(s)
    is_palindrome, longest_substring = find_longest_palindromic_substring(s)
    return (is_palindrome, longest_substring)

# Example usage:
print(is_palindrome_and_longest_substring("A man, a plan, a canal: Panama"))
```
