def is_match(str_a: str, str_b: str) -> bool:
    def match(start_a, start_b, memo):
        if (start_a, start_b) in memo:
            return memo[(start_a, start_b)]

        if start_a >= len(str_a) or start_b >= len(str_b):
            return start_a == len(str_a) and start_b == len(str_b)

        if str_b[start_b] == '.' or str_a[start_a] == str_b[start_b]:
            result = match(start_a + 1, start_b + 1, memo)
        else:
            result = False

        memo[(start_a, start_b)] = result
        return result

    memo = {}
    return match(0, 0, memo)
