def min_subset_difference(arr: List[int]) -> int:
    total_sum = sum(arr)
    half_sum = total_sum // 2

    def find_min_diff(start_index: int, current_sum: int) -> int:
        if current_sum == half_sum:
            return 0
        if current_sum > half_sum or current_sum < half_sum or current_sum < start_index:
            return float('inf')

        if memo[start_index][current_sum] is not None:
            return memo[start_index][current_sum]

        memo[start_index][current_sum] = min(find_min_diff(start_index + 1, current_sum + arr[start_index]),
                                            find_min_diff(start_index + 1, current_sum),
                                            find_min_diff(start_index + 1, current_sum - arr[start_index]))
        return memo[start_index][current_sum]

    memo = [[None] * (half_sum + 1) for _ in range(len(arr))]

    return find_min_diff(0, 0)
