from typing import List

class PriorityQueue:
    def __init__(self):
        self.queue = []

    def is_empty(self):
        return len(self.queue) == 0

    def insert(self, item, priority):
        self.queue.append((item, priority))
        self.queue.sort(key=lambda x: x[1])  # sort by priority

    def pop(self):
        if not self.is_empty():
            return self.queue.pop(0)
        else:
            raise IndexError("pop from empty priority queue")

    def peek(self):
        """Returns the data of the item with the lowest priority without removing it from the queue"""
        if not self.is_empty():
            return self.queue[0][0]
        else:
            raise IndexError("peek from empty priority queue")

    def update_priority(self, item, new_priority):
        """Updates the priority of a given item and repositions it in the queue according to its new priority"""
        for i, (j, priority) in enumerate(self.queue):
            if j == item:
                self.queue[i] = (item, new_priority)
                self.queue.sort(key=lambda x: x[1])  # re-sort the queue
                return
        raise ValueError(f"Item {item} not found in the priority queue")

def schedule_tasks(tasks: List[str], priorities: List[int]) -> List[str]:
    pq = PriorityQueue()
    for task, priority in zip(tasks, priorities):
        pq.insert(task, priority)
    result = [pq.pop()[0] for _ in range(len(tasks))]
    return result
```

