from typing import List

def countDistinctElementsInEverySubarray(arr: List[int], k: int) -> List[int]:
    n = len(arr)
    prefix_set = {}
    distinct_count = []
    left = 0

    for right in range(n):
        if right > 0:
            arr[right] += arr[right - 1]

        if right >= k:
            if arr[right] not in prefix_set:
                prefix_set[arr[right]] = 1
            else:
                prefix_set[arr[right]] += 1

            if right - k + 1 >= 0:
                left_item = arr[right - k + 1]
                count = prefix_set[left_item]

                if left_item not in prefix_set:
                    distinct_count.append(count)
                else:
                    distinct_count.append(count - prefix_set[left_item])

                prefix_set[left_item] -= 1
                if prefix_set[left_item] == 0:
                    del prefix_set[left_item]

        if right >= k - 1:
            distinct_count.append(len(prefix_set))

    return distinct_count
```

