from typing import List, Tuple

class MergeIntervals:
    def __init__(self, threshold: int) -> None:
        self.threshold = threshold
        self.intervals = []

    def insert(self, interval: Tuple[int, int]) -> None:
        if not self.intervals or self.intervals[-1][1] < interval[0]:
            self.intervals.append(interval)
        else:
            for i in range(len(self.intervals) - 1, -1, -1):
                if self.intervals[i][1] >= interval[0]:
                    if self.intervals[i][1] < interval[1]:
                        self.intervals[i] = (self.intervals[i][0], interval[1])
                    break
            if i != -1:
                self.intervals.insert(i, interval)
            else:
                self.intervals.append(interval)

    def get_intervals(self) -> List[Tuple[int, int]]:
        return self.intervals

