        for j in range(len(binary_sequence)):
            # Append the current binary string unchanged
            new_sequence.append(binary_sequence[j])
            # Append binary strings with a '1' added to the end
            new_sequence.append(binary_sequence[j] + '1')
            # Append binary strings with a '0' added to the end, avoiding duplicates
            if j > 0 and binary_sequence[j-1] != binary_sequence[j] + '0':
                new_sequence.append(binary_sequence[j] + '0')
