def min_portals_required(portals: List[Tuple[int, int, int, int]], queries: List[Tuple[int, int, int, int]]) -> List[int]:
    def can_pass(portals, query):
        x, y, dx, dy = query
        portals_x, portals_y = 0, 0
        portals_dx, portals_dy = 0, 0

        for p in portals:
            px, py, pdx, pdy = p
            if pdx == 0:
                portals_x += 1
            else:
                portals_y += 1

            if pdy == 0:
                portals_dx += 1
            else:
                portals_dy += 1

            if px == x and py == y:
                break

        dx %= portals_dx
        dy %= portals_dy

        if dx == 0 and dy == 0:
            return portals_x + portals_y

        if dx == 0:
            return portals_x + portals_y + 1
        if dy == 0:
            return portals_x + portals_y + 1

        return portals_x + portals_y + max(dx, dy)

    return [can_pass(portals, q) if q in portals else -1 for q in queries]
```
