import re
from collections import defaultdict

# Define the transformation rules
transformation_rules = {
    '0': '0',
    '1': '!',
    '7': '&',
    'a': 'c',
    'A': 'C',
    'e': 'i',
    'E': 'I',
    'o': 'q',
    'O': 'Q',
    'u': 'v',
    'U': 'V',
    'z': 'z',
    'Z': 'Z',
    '9': '9',
}

def transform_char(c):
    if c in transformation_rules:
        return transformation_rules[c]
    return c

def transform_username(username):
    for char in username:
        if char.isalpha():
            username = username.replace(char, transform_char(char.lower()))
    return username

def can_register(new_username, existing_usernames):
    new_transformed = transform_username(new_username)
    for existing_username in existing_usernames:
        existing_transformed = transform_username(existing_username)
        # Check for transformations
        if re.search(r'[!&]', new_transformed) and re.search(r'[!&]', existing_transformed):
            continue
        if re.search(r'[!&]', new_transformed) and re.search(r'[!&]', new_transformed):
            continue
        if re.search(r'[!&]', new_transformed) and re.search(r'[!&]', existing_transformed):
            continue
        # Check for case conversion
        if new_transformed.lower() != existing_transformed.lower():
            continue
        # Check for shifting
        for i, char in enumerate(new_transformed):
            if i == 0:
                continue
            if char != existing_transformed[i-1]:
                continue
            if i % 2 == 0:
                continue
            if char == 'a' and existing_transformed[i-1] == 'c':
                continue
            if char == 'e' and existing_transformed[i-1] == 'i':
                continue
            if char == 'o' and existing_transformed[i-1] == 'q':
                continue
            if char == 'O' and existing_transformed[i-1] == 'I':
                continue
            if char == 'u' and existing_transformed[i-1] == 'v':
                continue
            if char == 'U' and existing_transformed[i-1] == 'V':
                continue
            if char == 'z' and existing_transformed[i-1] == 'z':
                continue
        # Check for digit replacement
        if new_transformed.lower() != existing_transformed.lower():
            continue
        if new_transformed.lower().replace('1', '!') != existing_transformed.lower().replace('1', '!'):
            continue
        if new_transformed.lower().replace('7', '&') != existing_transformed.lower().replace('7', '&'):
            continue
    return True

