def find_longest_subsequence(arr, target_sum):
    n = len(arr)
    dp = [[False] * (target_sum + 1) for _ in range(n + 1)]
    dp[0][0] = True  # Empty subsequence sum 0

    for i in range(1, n + 1):
        for j in range(target_sum + 1):
            if dp[i - 1][j]:
                dp[i][j] = True
            elif arr[i - 1] <= j:
                dp[i][j] = dp[i - 1][j - arr[i - 1]]

    max_len = 0
    subsequence = []
    for i in range(n, 0, -1):
        if dp[i][target_sum]:
            max_len = i
            subsequence = arr[:i]
            break

    return max_len, subsequence

def longest_subsequence_by_sum(arr, target_sum):
    n = len(arr)
    max_len = 0
    subsequence = []

    for start in range(n):
        for end in range(start, n):
            subsequence_sum = sum(arr[start:end + 1])
            if subsequence_sum <= target_sum and end - start + 1 > max_len:
                max_len = end - start + 1
                subsequence = arr[start:end + 1]

    return max_len, subsequence
