This solution uses dynamic programming to determine if a subsequence of a given length can be found with a sum less than or equal to the target. It iterates through all possible subsequences and checks their sums, updating the maximum length and corresponding subsequence as it goes. The `longest_subsequence_by_sum` function is a more straightforward implementation that iterates through the array only once, finding the longest subsequence directly.

```python
def find_longest_subsequence(arr, target_sum):
    n = len(arr)
    dp = [[0] * (target_sum + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(target_sum + 1):
            if arr[i - 1] <= j:
                dp[i][j] = max(dp[i - 1][j], 1 + dp[i - 1][j - arr[i - 1]])
            else:
                dp[i][j] = dp[i - 1][j]

    max_length = 0
    subsequence = []
    for j in range(target_sum, -1, -1):
        if dp[n][j] > max_length:
            max_length = dp[n][j]
            subsequence = arr[n - max_length:n]

    return max_length, subsequence

def longest_subsequence_by_sum(arr, target_sum):
    n = len(arr)
    subsequence = [0] * (n + 1)
    dp = [0] * (target_sum + 1)

    for i in range(1, n + 1):
        max_length, subsequence[i] = find_longest_subsequence(arr[:i], target_sum)
        if max_length > 0:
            dp[target_sum] = max(dp[target_sum], max_length)
            for j in range(target_sum, subsequence[i] - 1, -1):
                dp[j] = max(dp[j], dp[j - subsequence[i]] + 1)

    return dp[target_sum], subsequence[target_sum]

