def find_max_without_consecutive_duplicates(nums):
    if not nums:
        return 0

    # Initialize variables to track the maximum sum including and excluding the last two elements
    incl = 0  # Maximum sum including the last element
    excl = 0  # Maximum sum excluding the last element

    for num in nums:
        # Update incl to be the maximum of the current number itself or the sum of last two elements
        incl, excl = excl + num, max(incl, excl)

    # Return the maximum of incl and excl, which represents the maximum sum including or excluding the last element
    return max(incl, excl)
