from typing import List, Tuple

class PanelManager:
    def __init__(self):
        self.panel_stack = []

    def create_panel(self, panel_id: str, height: int, width: int, y: int, x: int) -> None:
        self.panel_stack.append({"id": panel_id, "size": (height, width), "pos": (y, x), "visible": True})

    def move_panel(self, panel_id: str, y: int, x: int) -> None:
        for i, panel in enumerate(self.panel_stack):
            if panel["id"] == panel_id:
                self.panel_stack[i]["pos"] = (y, x)
                break

    def show_panel(self, panel_id: str) -> None:
        for i, panel in enumerate(self.panel_stack):
            if panel["id"] == panel_id:
                self.panel_stack[i]["visible"] = True
                break

    def hide_panel(self, panel_id: str) -> None:
        for i, panel in enumerate(self.panel_stack):
            if panel["id"] == panel_id:
                self.panel_stack[i]["visible"] = False
                break

    def top_panel(self, panel_id: str) -> None:
        for i, panel in enumerate(self.panel_stack):
            if panel["id"] == panel_id:
                self.panel_stack.insert(0, panel)
                break

    def bottom_panel(self, panel_id: str) -> None:
        for i, panel in enumerate(self.panel_stack):
            if panel["id"] == panel_id:
                self.panel_stack.append(panel)
                break

    def delete_panel(self, panel_id: str) -> None:
        for i, panel in enumerate(self.panel_stack):
            if panel["id"] == panel_id:
                self.panel_stack.pop(i)
                break

def panel_manager(commands: List[Tuple[str, ...]]) -> List[str]:
    manager = PanelManager()
    for cmd, *args in commands:
        if cmd == "CREATE":
            manager.create_panel(*args)
        elif cmd == "MOVE":
            manager.move_panel(*args)
        elif cmd == "SHOW":
            manager.show_panel(*args)
        elif cmd == "HIDE":
            manager.hide_panel(*args)
        elif cmd == "TOP":
            manager.top_panel(*args)
