        row, col, distance = queue.popleft()
        if row == rows - 1 and col == cols - 1:
            return distance

        for dr, dc in directions:
            r, c = row + dr, col + dc
            if 0 <= r < rows and 0 <= c < cols and grid[r][c] == 0:
                grid[r][c] = 1  # Mark as visited
                queue.append((r, c, distance + 1))

    return -1
