    if grid[0][0] == 1 or grid[rows-1][cols-1] == 1:
        return -1

    queue = [(0, 0, 1)]  # (row, col, steps)
    visited = set([(0, 0)])

    while queue:
        row, col, steps = queue.pop(0)
        if row == rows-1 and col == cols-1:
            return steps

        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
