def detectDupesWithIndex(t):
    """
    Identifies duplicate entries in a tuple and returns a dictionary with the duplicates and their indices.

    :param t: Tuple of elements to be checked for duplicates.
    :return: Dictionary with duplicates as keys and {first_index, last_index} as values.
    """
    # Dictionary to hold the index pairs for duplicates
    dupes_with_indices = {}

    # Dictionary to hold the original indices
    original_indices = {}

    # Iterate over the tuple to find duplicates
    for i, value in enumerate(t):
        if value in original_indices:
            # Duplicate found, update the dictionary with the index pair
            dupes_with_indices[value] = {original_indices[value], i}
        else:
            # First occurrence of the value, add it to the dictionary of original indices
            original_indices[value] = i

    # Filter out duplicates with only one occurrence
    return {key: value for key, value in dupes_with_indices.items() if len(value) > 1}

