def detectDupesWithIndex(t):
    """
    This function checks if a tuple contains more than one duplicate entry.
    If duplicates are found, it returns a dictionary with the duplicate value,
    the index at which it was first found, and the index at which it was last found.
    If no duplicates are found, it returns an empty dictionary.
    """
    # Initialize an empty dictionary to store duplicates
    duplicates = {}

    # Sort the tuple for easier checking of duplicates
    sorted_tuple = tuple(sorted(t))

    # Iterate through the tuple in a sorted manner to find duplicates
    for index, value in enumerate(sorted_tuple):
        # Check if the current value is the same as the next value
        if index + 1 < len(sorted_tuple) and sorted_tuple[index + 1] == value:
            duplicates[value] = (index, index + 1)

    # Return the dictionary of duplicates or an empty dictionary
    return duplicates if duplicates else {}

