def is_subset_sum(arr, n, K):
    # If the target is 0, then the subset is present
    if K == 0:
        return True
    # If any element is greater than K, then no subset can sum up to K
    if arr[0] > K:
        return False
    # If first element is greater than K, then ignore it
    if arr[0] > K:
        return is_subset_sum(arr[1:], n, K)
    # If K is greater than arr[0], then ignore this element
    elif K > arr[0]:
        return is_subset_sum(arr[1:], n, K)
    else:
        # Take the element and check if the rest of the array can form the sum
        return is_subset_sum(arr[1:], n - 1, K - arr[0]) or is_subset_sum(arr[1:], n, K)

