def is_subset_sum(arr, n, K):
    # Initialize a DP table where dp[i][j] is True if there is a subset of arr[0..i-1] that sums up to j
    dp = [[False] * (K+1) for _ in range(n+1)]
    dp[0][0] = True  # Base case: empty subset sums to 0

    # Fill the DP table
    for i in range(1, n+1):
        for j in range(K+1):
            dp[i][j] = dp[i-1][j]  # Current element is not included
            if j >= arr[i-1]:
                dp[i][j] |= dp[i-1][j-arr[i-1]]  # Current element is included

    # Check if the target sum K can be achieved
    return dp[n][K]

def solve_subsetsum_problem(T, test_cases):
    for _ in range(T):
        n, K = map(int, input().split())
        arr = list(map(int, input().split()))
        print("POSSIBLE" if is_subset_sum(arr, n, K) else "IMPOSSIBLE")
