def sorted_array_to_bst(nums: List[int]) -> TreeNode:
    def helper(nums, start, end):
        if start > end:
            return None

        mid = (start + end) // 2
        root = TreeNode(nums[mid])
        root.left = helper(nums, start, mid - 1)
        root.right = helper(nums, mid + 1, end)
        return root

    return helper(nums, 0, len(nums) - 1)

def print_level_order(root: TreeNode) -> List[int]:
    def level_order(root, level, levels):
        if root:
            if len(levels) < level + 1:
                levels.append([])
            levels[level].append(root.val)
            level_order(root.left, level + 1, levels)
            level_order(root.right, level + 1, levels)

    levels = []
    level_order(root, 0, levels)
    return [item for sublist in levels for item in sublist]

