    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None

def sorted_array_to_bst(nums: List[int]) -> TreeNode:
    def bst_build(start, end):
        if start > end:
            return None
        mid = (start + end) // 2
        node = TreeNode(nums[mid])
        node.left = bst_build(start, mid - 1)
        node.right = bst_build(mid + 1, end)
        return node

    return bst_build(0, len(nums) - 1)

def print_level_order(root: TreeNode) -> List[int]:
    if not root:
        return []

    result = []
    queue = [root]

    while queue:
        level = []
        for _ in range(len(queue)):
            node = queue.pop(0)
            level.append(node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        result.append(level)

    return result

