def is_interesting_sequence(k: int, sequence: str) -> str:
    def has_k_consecutive_digits(s: str, k: int) -> bool:
        for i in range(len(s) - k + 1):
            if s[i:i+k] == str(k):
                return True
        return False

    def has_odd_length_consecutive_digits(s: str, k: int) -> bool:
        for i in range(len(s) - k + 1):
            if len(set(s[i:i+k])) == 1 and s[i] != '0':
                return True
        return False

    def has_consecutive_odds(s: str, k: int) -> bool:
        for i in range(len(s) - k + 1):
            if set(s[i:i+k]).issuperset({'1', '3', '5', '7', '9'}):
                return True
        return False

    if k == 1:
        if len(sequence) < 3:
            return "YES"
        else:
            return "NO"

    for i in range(2, k + 1):
        if has_k_consecutive_digits(sequence, i) or has_odd_length_consecutive_digits(sequence, i) or has_consecutive_odds(sequence, i):
            return "YES"
    return "NO"
