def remaining_sellers(S: int, M: int, mergers: List[Tuple[int, int]]) -> int:
    # Count the number of times each seller is merged with another seller
    merged_with_count = {seller: 0 for seller in range(1, S+1)}
    for u, v in mergers:
        merged_with_count[u] += 1
        merged_with_count[v] += 1

    # Remove the sellers that have been merged with their own number of times
    for seller, count in merged_with_count.items():
        if count > 1:
            merged_with_count[seller] -= count - 1

    # Calculate the remaining sellers by subtracting the count of merged sellers from the initial count
    remaining = S - sum(merged_with_count.values())
    return remaining
