```python
def can_split_into_k_consecutive_subarrays(n, k, arr):
    # Check if the total sum of the array can be evenly divided by k
    total_sum = sum(arr)
    if total_sum % k != 0:
        return "NO"

    # Check if it's possible to split the array into k consecutive subarrays with equal sums
    target_sum = total_sum // k
    current_sum = 0
    for i, num in enumerate(arr):
        current_sum += num
        if current_sum == target_sum:
            if i + 1 == n or sum(arr[i+1:]) == target_sum:
                return "YES"

    return "NO"
