def sieve_of_eratosthenes(n: int) -> List[int]:
    if n <= 1:
        return []

    primes = [True] * n
    primes[0], primes[1] = False, False  # 0 and 1 are not prime

    for i in range(2, int(n**0.5) + 1):
        if primes[i]:
            for j in range(i*i, n, i):
                primes[j] = False

    return [i for i in range(2, n) if primes[i]]
