def find_single_number(nums: list[int]) -> int:
    if not nums:
        return None

    # Initialize the result with the first element
    result = nums[0]

    # Create a set to track the numbers we've seen
    seen = set()

    for num in nums:
        # If the number has been seen before, update the result with the current number
        if num in seen:
            result = num
        else:
            seen.add(num)

    return result

def longest_unique_substring(s: str) -> int:
    if not s:
        return 0

    max_length = 0
    start = 0
    char_index_map = {}

    for end in range(len(s)):
        if s[end] in char_index_map:
            start = max(start, char_index_map[s[end]] + 1)
        char_index_map[s[end]] = end
        max_length = max(max_length, end - start + 1)

    return max_length
