        self.table = new_table
        self.size = new_size
        self.count = 0
        for bucket in old_table:
            if bucket:
                for key, value in bucket:
                    self.put(key, value)

    def get_load_factor(self):
        """ Compute and return the current load factor of the hashtable.
        >>> ht = ResizableHashTable()
        >>> ht.put(1, 'a')
        >>> ht.put(2, 'b')
        >>> ht.put(3, 'c')
        >>> ht.get_load_factor()  # Should return close to 0.375 (3/8)
        """        
        return self.count / self.size
