        if node is None:
            return []
        if node.left is None and node.right is None:
            return [path + str(node.val)]
        left_paths = helper(node.left, path + str(node.val) + '->')
        right_paths = helper(node.right, path + str(node.val) + '->')
        return left_paths + right_paths

