import math

class SensorNetwork:
    def __init__(self, n, threshold):
        self.network = [None] * n
        self.threshold = threshold
        self.initialize_network()

    def initialize_network(self):
        for i in range(len(self.network)):
            self.network[i] = []

    def update_reading(self, sensor_id, reading):
        self.network[sensor_id].append(reading)

    def average_reading(self, sensor_id):
        if len(self.network[sensor_id]) == 0:
            return 0.0
        readings = [reading for reading in self.network[sensor_id] if reading is not None]
        if len(readings) < 2:
            return float(readings[0])
        return sum(readings) / len(readings)

    def network_status(self):
        malfunctioning_sensors = []
        for i in range(len(self.network)):
            if self.network[i]:
                avg_reading = self.average_reading(i)
                variance = sum((reading - avg_reading) ** 2 for reading in self.network[i]) / len(self.network[i])
                if variance > self.threshold ** 2:
                    malfunctioning_sensors.append(i)
        return malfunctioning_sensors


