def generate_spiral_matrix(n):
    def dfs(x, y, dx, dy):
        if not (0 <= x < n and 0 <= y < n):
            return
        if x == y == n - 1:
            return [x, y]
        dx, dy = dx + 1, dy + 1
        if x == 0 or y == 0 or x == n - 1 or y == n - 1:
            return [x, y]
        dfs(x + dx, y + dy, dx, dy)
        return [x, y]

    def fill_cells(matrix, x, y, dx, dy):
        while True:
            matrix[x][y] = i
            if not (0 <= x < n and 0 <= y < n):
                return
            x += dx
            y += dy
            if matrix[x][y] != 0:
                return

    matrix = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(1, n * n + 1):
        x, y = dfs(0, 0, 0, 1)
        fill_cells(matrix, x, y, 1, 1)

    return matrix

