        self.history = []

    def add_to_history(self, input_line: str) -> None:
        self.history.append(input_line)

    def get_history(self) -> list:
        return self.history

    def complete(self, text: str, local_scope: dict) -> list:
        """ Given an incomplete text and a dictionary representing the local scope, returns a list of possible completions. """
        # Identify potential completions based on the input text and local scope
        completions = []
        for key, value in local_scope.items():
            # Check if the input text starts with the key
            if text.startswith(key):
                completions.append(key)
            # Check if the input text starts with the value of the key
            if isinstance(value, dict):
                sub_completions = self.complete(text, value)
                if sub_completions:
                    for sub_completion in sub_completions:
                        completions.append(f"{key}={sub_completion}")
        return completions
