class InteractiveEditor:
    def __init__(self):
        self.history = []
        self.local_vars = {}
        self.completion_candidates = set()

    def add_to_history(self, input_line: str) -> None:
        """ Adds an input line to the history. """
        self.history.append(input_line)

    def get_history(self) -> list:
        """ Returns the list of all input lines stored in history. """
        return self.history

    def complete(self, text: str, local_scope: dict) -> list:
        """ Given an incomplete text and a dictionary representing the local scope, returns a list of possible completions. """
        if text in self.completion_candidates:
            return list(self.completion_candidates)
        for key, value in local_scope.items():
            if key.startswith(text):
                self.completion_candidates.add(key)
        return list(self.completion_candidates)

    def add_to_local_scope(self, key, value):
        """ Adds a key-value pair to the local scope. """
        self.local_vars[key] = value

    def remove_from_local_scope(self, key):
        """ Removes a key-value pair from the local scope. """
        if key in self.local_vars:
            del self.local_vars[key]
