import re

def evaluate_expression(expression: str) -> float:
    # Replace spaces around operators, numbers, and parentheses
    expression = re.sub(r'\s*([\+\-\*\/])\s*', r'\1', expression)
    expression = re.sub(r'\s*([\+\-\*\/])\s*', r'\1', expression)
    expression = re.sub(r'\s*\(\s*[\+\-\*\/]\s*\)\s*', r'\1', expression)

    # Evaluate the expression
    expression = expression.replace(' ', '')
    stack = []
    i = 0
    while i < len(expression):
        if expression[i] == '(':
            stack.append(i)
        elif expression[i] == ')':
            start = stack.pop()
            yield eval(expression[start:i])
        elif expression[i] in '+-*/':
            while stack and stack[-1] in '+-*/':
                yield eval(''.join(stack))
                stack.pop()
            stack.append(expression[i])
        else:
            while stack and precedence(expression[i]) <= precedence(stack[-1]):
                yield eval(''.join(stack))
                stack.pop()
            stack.append(expression[i])
        i += 1
    while stack:
        yield eval(''.join(stack))

def precedence(op):
    if op in '+-':
        return 1
    elif op in '*/':
        return 2
    else:
        return 0

