def max_water_trapped(buildings: List[int]) -> int:
    if not buildings or len(buildings) < 3:
        return 0

    left_max = buildings[0]
    right_max = buildings[-1]
    max_water = 0
    left_index = 1
    right_index = len(buildings) - 2

    while left_index <= right_index:
        if left_max <= right_max:
            if buildings[left_index] >= left_max:
                left_max = buildings[left_index]
            else:
                max_water += left_max - buildings[left_index]
            left_index += 1
        else:
            if buildings[right_index] >= right_max:
                right_max = buildings[right_index]
            else:
                max_water += right_max - buildings[right_index]
            right_index -= 1

    return max_water
