def findAndReplacePattern(words, pattern):
    def match(word):
        if len(word) != len(pattern):
            return False
        mapping = {}
        inverse_mapping = {}
        for w, p in zip(word, pattern):
            if w not in mapping:
                if p in inverse_mapping:
                    return False
                mapping[w] = p
                inverse_mapping[p] = w
            elif mapping[w] != p:
                return False
        return True

