def findAndReplacePattern(words, pattern):
    def match(word):
        # Create a mapping from pattern to word and vice versa
        map1 = {}
        map2 = {}

        # Check if the word matches the pattern
        for i in range(len(word)):
            if word[i] in map2:
                if map2[word[i]] != pattern[i]:
                    return False
            else:
                map2[word[i]] = pattern[i]

            if pattern[i] in map1:
                if map1[pattern[i]] != word[i]:
                    return False
            else:
                map1[pattern[i]] = word[i]

        # Check if all characters are unique in the word
        for char in word:
            if word.count(char) > 1:
                return False

        return True

    # Filter words that match the pattern
    return list(filter(match, words))
