def can_form_palindrome(S):
    """
    Determines if the string S can be transformed into a palindrome by moving any character to the front.

    :param S: A string consisting of lowercase English letters.
    :return: "Yes" if the string can be transformed into a palindrome, "No" otherwise.
    """
    # Count the frequency of each character
    char_freq = {}
    for char in S:
        if char in char_freq:
            char_freq[char] += 1
        else:
            char_freq[char] = 1

    # Count the number of characters that need to be moved to the front
    moves_needed = sum(1 for freq in char_freq.values() if freq % 2 != 0)

    # If the number of moves needed is odd, it's impossible to form a palindrome
    if moves_needed % 2 != 0:
        return "No"
    else:
        return "Yes"
