from functools import cmp_to_key

def compare_complexities(a, b):
    """
    Compare two Big-O notations and return a negative integer, zero, or a positive integer
    as the first argument is less than, equal to, or greater than the second.
    """
    complexities_map = {'O(1)': 1, 'O(log N)': 2, 'O(N)': 3, 'O(N log N)': 4, 'O(N^2)': 5, 'O(2^N)': 6}
    a, b = a.lower(), b.lower()
    return complexities_map[a] - complexities_map[b]

def average_time_complexity(T, complexities):
    complexities.sort(key=cmp_to_key(compare_complexities))
    complexities_count = {}
    for comp in complexities:
        complexities_count[comp] = complexities_count.get(comp, 0) + 1
    total_count = sum(complexities_count.values())

    median_complexity = None
    for comp in complexities:
        if complexities_count[comp] == total_count // 2:
            median_complexity = comp
            break

    if median_complexity is None:
        median_complexity = complexities[total_count // 2 - 1]

    return "O({})".format(median_complexity)

