def min_trees_to_cut(n: int, heights: List[int]) -> int:
    def dp(index: int, prev_height: int) -> int:
        if index == n:
            return 0
        if index == n - 1:
            return 1
        if heights[index] == prev_height:
            return 1 + dp(index + 1, heights[index + 1])
        else:
            return min(dp(index + 1, heights[index + 1]), dp(index + 1, heights[index + 1]))

    return dp(0, heights[0])
