            for r in kSum(nums[i+1:], target - n, k-1):
                res.append([n] + r)
            nums = nums[:i] + nums[i+1:]

        return res or [[target]]

    def twoSum(nums, target):
        seen = {}
        res = []
        for i, n in enumerate(nums):
            if n in seen:
                res.append([n] + seen[n])
            seen[target - n] = [n, target - n]

        return res

    return kSum(sorted(nums), target, 4)
