        if not nums:
            return []
        if k == 2:
            return twoSum(nums, target)
        res = []
        for i in range(len(nums)):
            if i == 0 or nums[i] != nums[i - 1]:
                for p in kSum(nums[i + 1:], target - nums[i], k - 1):
                    res.append([nums[i]] + p)
        return res

    nums.sort()
    for i in range(len(nums)):
        if i == 0 or nums[i] != nums[i - 1]:
            for j in kSum(nums[i + 1:], target - nums[i], 3):
                res = [nums[i]] + j
                res.sort()
                if res not in res_set:
                    res_set.add(res)
    return res_set

