def fourSum(nums, target):
    nums.sort()  # Sort the array to handle duplicates and for easier triple_sum and two_sum calls
    return findQuadruplets(nums, target, 4)

def twoSum(nums, target):
    return twoSumHelper(nums, target, 0, len(nums) - 1)

def twoSumHelper(nums, target, start, end):
    if start >= end:
        return []

    if nums[start] + nums[end] > target:
        return twoSumHelper(nums, target, start + 1, end)
    elif nums[start] + nums[end] < target:
        return twoSumHelper(nums, target, start, end - 1)
    else:
        return [nums[start], nums[end], twoSumHelper(nums, target - nums[start] - nums[end], start + 1, end - 1)]

def findQuadruplets(nums, target, k):
    quadruplets = []
    for i in range(len(nums) - k + 1):
        for j in range(i + 1, len(nums) - k + 2):
            triple_sum = twoSum(nums, target - nums[i] - nums[j], j + 1, len(nums) - 1)
            for triplet in triple_sum:
                quadruplets.append((nums[i], nums[j], nums[triplet[0]], nums[triplet[1]]))
    return quadruplets
