import html5lib

def convert_html_entities(text: str) -> str:
    """
    Replaces HTML named entities in the given text with their corresponding Unicode characters.
    """
    html_entities = html5lib.entities.get_all()
    entity_map = {entity.name: entity.value for entity in html_entities}

    def replace_entity(match):
        replacement = entity_map.get(match.group(0))
        if replacement:
            return replacement
        else:
            return match.group(0)

    return re.sub(r"&(#?)([a-zA-Z0-9]+);", replace_entity, text)

# Check function to verify the correctness of the solution
def check_solution():
    test_cases = [
        ("Greater than: &gt;, less than: &lt;", "Greater than: >, less than: <"),
        ("Ampersand: &amp;, Aacute: &Aacute;, Unknown: &unknown;", "Ampersand: &, Aacute: Á, Unknown: &unknown;"),
        ("&lt;&gt;&amp;&amp;", "&lt;&gt;&amp;&amp;")
    ]

    for text, expected in test_cases:
        result = convert_html_entities(text)
        assert result == expected, f"Error: Expected {expected}, got {result}"
    print("All test cases passed!")

check_solution()
