def count_islands(matrix: List[List[int]]) -> int:
    def dfs(x, y):
        if x < 0 or x >= len(matrix) or y < 0 or y >= len(matrix[0]) or matrix[x][y] != 1:
            return
        matrix[x][y] = -1  # Mark as visited
        dfs(x + 1, y)
        dfs(x - 1, y)
        dfs(x, y + 1)
        dfs(x, y - 1)

    count = 0
    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            if matrix[i][j] == 1:
                dfs(i, j)
                count += 1
    return count
