        dfs(x + 1, y)  # Check down
        dfs(x - 1, y)  # Check up
        dfs(x, y + 1)  # Check right
        dfs(x, y - 1)  # Check left

    count = 0
    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            if matrix[i][j] == 1:
                dfs(i, j)
                count += 1
    return count
