from typing import List

def find_peak_elements(lst: List[int]) -> List[int]:
    if not lst or len(lst) == 1:
        return []

    left, right = 0, len(lst) - 1

    while left < right:
        mid = (left + right) // 2
        if mid == 0 or mid == len(lst) - 1:
            return [lst[mid]] if lst[mid] > lst[mid - 1] and lst[mid] > lst[mid + 1] else []

        if lst[mid] > lst[mid - 1] and lst[mid] > lst[mid + 1]:
            return [lst[mid]] + find_peak_elements(lst[:mid]) + find_peak_elements(lst[mid + 1:])
        elif lst[mid] < lst[mid - 1]:
            right = mid - 1
        else:
            left = mid + 1

    return [lst[left]] if lst[left] > lst[left + 1] else []

