from typing import List

def smallestString(s: str, pairs: List[List[int]]) -> str:
    def find(x):
        if parents[x] != x:
            parents[x] = find(parents[x])
        return parents[x]

    def union(x, y):
        parents[find(x)] = find(y)

    parents = defaultdict(int)
    for pair in pairs:
        x, y = pair
        parents[x] = x
        parents[y] = y
        union(x, y)

    component_sizes = defaultdict(int)
    for i in range(len(s)):
        component_sizes[find(i)] += 1

    sorted_components = sorted(component_sizes.items(), key=lambda x: x[1], reverse=True)

    result = list(s)
    for size, index in sorted_components:
        for i in range(size):
            idx = index + i
            result[idx], result[idx + size] = result[idx + size], result[idx]
            if idx < len(s):
                union(idx, idx + size)

    return ''.join(result)
```

This Python function `smallestString` takes a string `s` and a list of pairs of indices in the string `pairs`, and returns the lexicographically smallest string that can be obtained by performing the allowed swaps. It uses a union-find data structure to manage the connected components and sorts the components to get the smallest configuration.

Here is a Python implementation of the `smallestString` function using the union-find data structure. The idea is to use the union-find structure to group characters together and then sort each group to achieve the lexicographically smallest configuration.

```python
class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.size = [1] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        rootX = self.find(x)
        rootY = self.find(y)
        if rootX != rootY:
            if self.rank[rootX] > self.rank[rootY]:
                self.parent[rootY] = rootX
                self.size[rootX] += self.size[rootY]
            else:
                self.parent[rootX] = rootY
                self.size[rootY] += self.size[rootX]
                if self.rank[rootX] == self.rank[rootY]:
                    self.rank[rootY] += 1

def smallestString(s, pairs):
    uf = UnionFind(len(s))
    for a, b in pairs:
        uf.union(a, b)

    char_groups = []
    for i in range(len(s)):
        if uf.find(i) not in char_groups:
            char_groups.append([uf.find(i)])

    for group in char_groups:
        group.sort()

    result = []
    for i in range(len(s)):
        result.append(s[uf.find(i)])

    return "".join(result)

# Example usage:
s = "cba"
pairs = [[0, 1], [1, 2]]
print(smallestString(s, pairs))  # Output: "aaa"
```

This solution works as follows:

1. We initialize a union-find data structure to manage the connected components of the string.
2. We iterate through the pairs and union the indices that need to be swapped.
3. We group the indices by their parent (union-find root) and sort each group.
4. Finally, we construct the result string by iterating through the original string and using the sorted indices.

This approach ensures that we can perform any number of swaps allowed and find the lexicographically smallest string configuration.

