def longest_contiguous_ones(s: str) -> int:
    n = len(s)
    dp = [[0] * n for _ in range(n)]  # DP table to store the length of the longest contiguous '1's ending at each position

    # Initialize the DP table for the first row and column
    for i in range(n):
        dp[i][i] = 1 if s[i] == '1' else 0

    # Fill the DP table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == '1':
                dp[i][j] = dp[i + 1][j] + 1
            else:
                dp[i][j] = dp[i][j - 1] + 1 if dp[i][j - 1] != 0 else 0

    # Find the maximum length of contiguous '1's
    max_length = max(max(row) for row in dp)
    return max_length
```

