from typing import List

def determinant(matrix: List[List[float]]) -> float:
    """Calculate the determinant of a matrix."""
    if len(matrix) != len(matrix[0]):
        raise ValueError("Matrix must be square")

    if len(matrix) == 1:
        return matrix[0][0]

    if len(matrix) == 2:
        return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]

    det = 0
    for col in range(len(matrix)):
        det += (-1) ** col * matrix[0][col] * determinant(get_minor(matrix, 0, col))
    return det

def get_minor(matrix: List[List[float]], row: int, col: int) -> List[List[float]]:
    """Return the minor matrix obtained by deleting a row and a column."""
    minor = []
    for i in range(len(matrix)):
        if i != row:
            minor_row = []
            for j in range(len(matrix)):
                if j != col:
                    minor_row.append(matrix[i][j])
            minor.append(minor_row)
    return minor

def adjugate(matrix: List[List[float]]) -> List[List[float]]:
    """Calculate the adjugate matrix of a matrix."""
    if len(matrix) != len(matrix[0]):
        raise ValueError("Matrix must be square")

    adj = []
    for col in range(len(matrix)):
        minor = get_minor(matrix, 0, col)
        det_minor = determinant(minor)
        adj.append([(-1) ** col * det_minor] + [minor[i][j] for i in range(len(minor)) for j in range(len(minor[i])) if j != col])
    return adj

def invert_matrix(matrix: List[List[float]]) -> List[List[float]]:
    """Invert a square matrix using the adjugate matrix."""
    if not matrix or not matrix[0]:
        raise ValueError("Matrix must be non-empty")
    if len(matrix) != len(matrix[0]):
        raise ValueError("Matrix must be square")

    det = determinant(matrix)
    if det == 0:
        raise ValueError("Matrix is singular and cannot be inverted")

    adj = adjugate(matrix)
    inv = [[adj[i][j] / det for j in range(len(matrix))] for i in range(len(matrix))]
    return inv
```

This solution introduces a new function `determinant` to calculate the determinant of the matrix, which is then used to determine if the matrix is invertible. If the matrix is singular (i.e., non-invertible), an error message is raised. The `adjugate` function is used to compute the adjugate matrix, which is then inverted using the formula `A^-1 = (1/det) * adj`. The solution is designed to be more robust and efficient, ensuring that all edge cases are handled gracefully.

