    line_numbers = set()
    for line in disassembled_code.split('\n'):
        if 'push' in line or 'pop' in line:
            line_numbers.add(line.split(' ')[1])

    return {
        'disassembled_code': disassembled_code,
        'global_vars': list(global_vars),
        'line_numbers': list(line_numbers)
