def longest_palindrome_length(n: int, s: str) -> int:
    odd_found = False
    max_length = 0

    # Iterate through each character in the string
    for i in range(n):
        # Check for the longest odd-length palindrome starting at i
        odd_length = 0
        for j in range(i, -1, -1):
            if s[j] != s[i]:
                break
            odd_length += 1

        # Check for the longest even-length palindrome starting at i
        even_length = 0
        for j in range(i + 1, n):
            if s[j] != s[i]:
                break
            even_length += 1

        # Update the maximum length found
        max_length = max(max_length, odd_length, even_length)

    # Add one to the maximum length if an odd-length palindrome was found
    return max_length + (1 if odd_found else 0)
