from typing import List

def combination_sum_topdown(nums: List[int], target: int) -> int:
    """
    Calculates the number of possible combinations that add up to target using a top-down approach with memoization.
    """
    memo = {}

    def dfs(remain):
        if remain == 0:
            return 1
        if remain < 0:
            return 0
        if remain not in memo:
            memo[remain] = sum(dfs(remain - num) for num in nums)
        return memo[remain]

    return dfs(target)

def combination_sum_bottom_up(nums: List[int], target: int) -> int:
    """
    Calculates the number of possible combinations that add up to target using a bottom-up approach.
    """
    dp = [0] * (target + 1)
    dp[0] = 1  # Base case: one way to make target 0

    for num in nums:
        for i in range(num, target + 1):
            dp[i] += dp[i - num]

    return dp[target]
```

