def min_steps_to_reach_bottom_right(M: int, N: int, k: int, grid: List[List[int]]) -> int:
    def dfs(x, y, steps, elevation_diff):
        if x == M - 1 and y == N - 1:
            return steps

        current_diff = grid[x][y] - elevation_diff
        if current_diff <= 0:
            return float('inf')

        min_steps = float('inf')
        for dx, dy in [[0, 1], [1, 0], [0, -1], [-1, 0]]:
            new_x, new_y = x + dx, y + dy
            if 0 <= new_x < M and 0 <= new_y < N:
                next_diff = grid[new_x][new_y] - elevation_diff
                if next_diff <= 0:
                    next_diff = -next_diff
                min_steps = min(min_steps, next_diff + steps + 1, dfs(new_x, new_y, steps + 1, elevation_diff + next_diff))

        return min_steps

    elevation_diff = grid[0][0]
    return dfs(0, 0, 0, elevation_diff)
