        self.val = val
        self.left = left
        self.right = right

class Solution:
    def countGoodNodes(self, edges: List[List[int]]) -> int:
        n = len(edges) + 1
        tree = [None] * n
        for u, v in edges:
            tree[u] = TreeNode(v)
            tree[v] = TreeNode(u)

        # Build the tree
        for u, v in edges:
            tree[u].left = tree[v]
            tree[v].left = tree[u]

        # Perform DFS to count good nodes
        def dfs(node, max_val):
            count = 1 if node.val >= max_val else 0
            for child in [node.left, node.right]:
                if child:
                    count += dfs(child, max(max_val, node.val))
            return count

        return dfs(tree[0], float('-inf'))
