            count = 0
            for i in range(len(arr) - 1):
                if arr[i] > arr[i + 1]:
                    count += i + 1
            return count

        def count_increasing_pairs(arr):
            count = 0
            for i in range(len(arr) - 1):
                if arr[i] >= arr[i + 1]:
                    count += len(arr) - 1 - i
            return count

