            pairs += decreasing_count * increasing_count
            if nums[i] > i:
                decreasing_count += count_decreasing_pairs(nums[i:])
            if nums[i] < i:
                increasing_count += count_increasing_pairs(nums[:i])
            pairs %= MOD

        return pairs
