class Solution:
    def minLargest(self, nums1: List[int], nums2: List[int]) -> int:
        # Helper function to get the least common multiple (LCM) of two numbers
        def lcm(a, b):
            return abs(a*b) // gcd(a, b)

        # Helper function to get the greatest common divisor (GCD) of two numbers
        def gcd(a, b):
            while b:
                a, b = b, a % b
            return a

        # Helper function to get the next power of 2 greater than or equal to n
        def next_power_of_2(n):
            return 1 << (n - 1).bit_length()

        # Helper function to find the smallest number in the array
        def find_smallest(arr):
            return min(arr)

        # Helper function to find the largest number in the array
        def find_largest(arr):
            return max(arr)

        # Helper function to get the sum of all elements in the array
        def get_sum(arr):
            return sum(arr)

        # Find the smallest number in nums1
        smallest_num1 = find_smallest(nums1)

        # Find the smallest number in nums2
        smallest_num2 = find_smallest(nums2)

        # Find the largest number in nums1
        largest_num1 = find_largest(nums1)

        # Find the largest number in nums2
        largest_num2 = find_largest(nums2)

        # Calculate the LCM of the smallest numbers
        lcm_smallest = lcm(smallest_num1, smallest_num2)

        # Calculate the sum of all numbers in nums1 and nums2
        total_sum1 = get_sum(nums1)
        total_sum2 = get_sum(nums2)

        # Calculate the minimum possible largest number
        min_largest = lcm_smallest + total_sum1 + total_sum2 - 1
        return min_largest
