        for num in range(10**n):
            # Convert the number to a string to easily rearrange digits
            num_str = str(num)
            # Check if the number is k-palindromic
            if self.is_k_palindromic(num_str, k):
                # Increment the count if the number is good
                count += 1

        return count

    def is_k_palindromic(self, num_str: str, k: int) -> bool:
        # Check if the number is k-palindromic
        # A number is k-palindromic if it is a palindrome and divisible by k
        for i in range(len(num_str) // 2):
            if num_str[i] != num_str[-(i + 1)]:
                return False
        return int(num_str) % k == 0

