class Solution:
    def countGoodIntegers(self, n: int, k: int) -> int:
        # If k is greater than 9, no good integers can be formed as all digits would be repeated
        if k > 9:
            return 0

        # If k is equal to 1, all integers with n digits can be good
        if k == 1:
            return n

        # Determine the count of good integers
        count = 0
        # Iterate over all possible first digits (0 to k-1)
        for digit in range(1, k + 1):
            # Generate the k-palindromic number with the current first digit
            k_palindrome = int(str(digit) * (n // 2) + digit * (n % 2))
            # Check if the number is divisible by k
            if k_palindrome % k == 0:
                count += 1

        return count
