import heapq

class Solution:
    def resultsArray(self, queries: List[List[int]], k: int) -> List[int]:
        # Initialize a list to store the distances to obstacles
        distances = []

        # Process each query
        for x, y in queries:
            # Calculate the distance to the origin
            distance = abs(x) + abs(y)

            # If there are less than k obstacles, add the new distance
            if len(distances) < k:
                heapq.heappush(distances, distance)
                heapq.heapify(distances)

            # If there are at least k obstacles, remove the smallest distance
            else:
                heapq.heappushpop(distances, distance)

            # Return the kth nearest obstacle or -1 if there are less than k obstacles
            return -1 if len(distances) < k else heapq.heappop(distances)
