class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        if not grid:
            return 0

        rows, cols = len(grid), len(grid[0])
        max_score = 0
        selected_cells = []

        # Iterate through each cell in the grid
        for r in range(rows):
            for c in range(cols):
                # Skip cells that are already in the selected cells
                if (r, c) in selected_cells:
                    continue

                # Calculate the score if this cell is selected
                score = sum(grid[r][i] for i in range(cols) if (r, i) not in selected_cells)

                # Update max_score if the current score is higher
                if score > max_score:
                    max_score = score
                    selected_cells.append((r, c))

                # Check the cell in the next row
                if r < rows - 1:
                    for c in range(cols):
                        if (r + 1, c) not in selected_cells:
                            score = sum(grid[r][i] for i in range(cols) if (r + 1, i) not in selected_cells)
                            if score > max_score:
                                max_score = score
                                selected_cells.append((r + 1, c))

        return max_score
