import collections

class Solution:
    def maxArea(self, height: int, positions: List[int], directions: str) -> int:
        # Initialize deque to store positions and their directions
        deque = collections.deque([(pos, dir) for pos, dir in zip(positions, directions)])
        max_area = 0

        while deque:
            pos, dir = deque.popleft()
            prev_pos = deque[0][0] if deque else -height

            # Calculate the area
            area = (pos - prev_pos) * min(height, max(height - pos, height - prev_pos))

            # Update max_area if the current area is greater
            max_area = max(max_area, area)

            # Move the deque to the next position in the same direction
            if dir == 'U':
                while deque and deque[-1][0] <= pos:
                    deque.pop()
            else:
                while deque and deque[0][0] >= pos:
                    deque.popleft()

        return max_area
