import heapq

class Cylinder:
    def __init__(self, height, position, direction):
        self.height = height
        self.position = position
        self.direction = direction

    def get_area(self):
        return min(self.position, self.height - self.position)

def max_area(height, positions, directions):
    # Create a max heap of cylinders based on the area
    cylinders = [Cylinder(height, pos, dir) for pos, dir in zip(positions, directions)]
    heapq.heapify(cylinders)

    max_area = 0
    current_height = 0
    while cylinders:
        current_cylinder = heapq.heappop(cylinders)
        if current_cylinder.get_area() > max_area:
            max_area = current_cylinder.get_area()
        current_height = max(current_height, current_cylinder.position)

        # If a piston has reached the end, change its direction
        if current_cylinder.direction == 'U' and current_cylinder.position == 0:
            current_cylinder.direction = 'D'
        elif current_cylinder.direction == 'D' and current_cylinder.position == height:
            current_cylinder.direction = 'U'

        # If the next piston has a higher position, add it to the heap
        next_cylinder = heapq.heappop(cylinders)
        if next_cylinder.position > current_height:
            heapq.heappush(cylinders, next_cylinder)

    return max_area
