class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        memo = [0] * n

        def maxScore(index, lastIndex):
            if index == n - 1:
                return 0

            if memo[index] != 0:
                return memo[index]

            maxScoreValue = 0
            for i in range(index + 1, n):
                if i > lastIndex:
                    maxScoreValue = max(maxScoreValue, (nums[i] * (i - index)) + maxScore(i, i))

            memo[index] = maxScoreValue
            return maxScoreValue

        return maxScore(0, -1)
