    def capture_pawn(self, knight_x, knight_y, pawn_x, pawn_y):
        # Calculate the minimum number of moves to capture the pawn
        min_moves = float('inf')
        directions = [(2, 1), (2, -1), (-2, 1), (-2, -1), (1, 2), (1, -2), (-1, 2), (-1, -2)]
        for dx, dy in directions:
            nx, ny = pawn_x, pawn_y
            for _ in range(8):
                nx += dx
                ny += dy
                if 0 <= nx < self.width and 0 <= ny < self.height:
                    if self.board[ny][nx] == 1:
                        min_moves = min(min_moves, self.moves_to_capture(pawn_x, pawn_y, nx, ny) + 1)
        return min_moves

    def moves_to_capture(self, x1, y1, x2, y2):
        dx, dy = x1 - x2, y1 - y2
        steps = 0
        while 0 <= dx < 2 and 0 <= dy < 2:
            dx += 2
            dy += 2
            steps += 1
        return steps

    def get_pawns_count(self):
        return len(self.pawns)

class Solution:
