            board.set_pawn_position(pos[0], pos[1])
        knight_x, knight_y = kx, ky

        moves = 0
        while board.get_pawns_count():
            moves += board.capture_pawn(knight_x, knight_y, board.pawns[0][0], board.pawns[0][1])
            board.set_pawn_position(board.pawns[0][0], board.pawns[0][1])
            board.pawns.pop(0)
        return moves
