class Solution:
    def maxMoves(self, kx: int, ky: int, positions: List[List[int]]) -> int:
        def knightMoves(knight, pawn):
            # Determine the number of moves the knight needs to make to reach the pawn
            moves = 0
            while knight != pawn:
                knight = (knight[0] + 2, knight[1] + 1)
                moves += 1
            return moves

        def minCaptures(knight, positions):
            # Find the minimum number of captures needed to reach the knight
            min_captures = float('inf')
            for pawn in positions:
                if knight != pawn:
                    capture_moves = knightMoves(knight, pawn) + knightMoves(pawn, knight)
                    min_captures = min(min_captures, capture_moves)
            return min_captures

        # Calculate the initial captures for the knight
        initial_captures = minCaptures((kx, ky), positions)

        # Initialize the maximum moves Alice can achieve
        max_moves = initial_captures

        # Calculate the maximum moves Alice can achieve by considering all possible pawn positions
        for i in range(len(positions)):
            for j in range(len(positions)):
                if i != j:
                    knight = (kx, ky)
                    pawn = positions[i]
                    new_captures = minCaptures(knight, positions[j])
                    max_moves = max(max_moves, initial_captures + new_captures)

        return max_moves
