class Solution:
    def findSafeWalk(self, grid: List[List[int]], health: int) -> bool:
        m, n = len(grid), len(grid[0])

        # Check if the starting point is unsafe
        if grid[0][0] == 1:
            health -= 1

        # Check if the ending point is unsafe
        if grid[-1][-1] == 1:
            health -= 1

        # Perform a depth-first search to find a safe path
        def dfs(x, y, health):
            if x < 0 or x >= m or y < 0 or y >= n or grid[x][y] == 1:
                return False
            if health <= 0:
                return False
            if grid[x][y] == 2:
                return True  # Found the goal
            grid[x][y] = 2  # Mark as visited
            health -= 1
            if dfs(x + 1, y, health) or dfs(x - 1, y, health) or dfs(x, y + 1, health) or dfs(x, y - 1, health):
                return True
            grid[x][y] = 0  # Unmark the cell
            return False

        # Start DFS from the top-left corner
        return dfs(0, 0, health) > 0
