import numpy as np

class Solution:
    def findSafeWalk(self, grid, health):
        m, n = len(grid), len(grid[0])
        visited = np.zeros((m, n), dtype=bool)
        queue = [(0, 0)]
        visited[0, 0] = True

        while queue:
            i, j = queue.pop(0)
            health -= grid[i][j] - 1

            if health <= 0:
                return False

            for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and not visited[ni, nj]:
                    visited[ni, nj] = True
                    queue.append((ni, nj))

        return health >= 1
