class Solution:
    def findSafeWalk(self, grid: List[List[int]], health: int) -> bool:
        def is_safe(cell, health):
            x, y = cell
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == 0:
                    health -= 1
                    if health <= 0:
                        return False
            return True

        m, n = len(grid), len(grid[0])
        if health <= 0:
            return False

        queue = deque([(0, 0, health)])
        visited = set([(0, 0)])

        while queue:
            x, y, curr_health = queue.popleft()
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == 0 and (nx, ny) not in visited:
                    new_health = curr_health - 1
                    if new_health < 0:
                        continue
                    visited.add((nx, ny))
                    queue.append((nx, ny, new_health))
                    if is_safe((nx, ny), new_health):
                        return True
        return False
