class Solution:
    def maxPathLength(self, coordinates: List[List[int]], k: int) -> int:
        prev = set()
        max_len = 0

        for i, (x1, y1) in enumerate(coordinates):
            if i == k:
                continue  # Skip the starting point

            # Try to extend the path backwards
            for x2, y2 in prev:
                if x2 < x1 and y2 < y1:
                    max_len = max(max_len, i - 1 + self.dfs(coordinates, x1, y1, k - 1))

            prev.add((x1, y1))

            # Try to extend the path forwards
            for x2, y2 in (prev - {(x1, y1)}):
                if x2 < x1 and y2 < y1:
                    max_len = max(max_len, i + 1 + self.dfs(coordinates, x2, y2, k - 1))

            prev.remove((x1, y1))

        return max_len

    def dfs(self, coordinates, x1, y1, k):
        if k == 0:
            return 1

        max_len = 0
        for x2, y2 in coordinates:
            if x2 > x1 and y2 > y1:
                max_len = max(max_len, 1 + self.dfs(coordinates, x2, y2, k - 1))

        return max_len
