        max_path = 1
        for i in range(k + 1, n):
            for j in range(i - 1, k, -1):
                if coordinates[i][0] > coordinates[j][0] and coordinates[i][1] > coordinates[j][1]:
                    dp[i] = max(dp[i], dp[j] + 1)
                    max_path = max(max_path, dp[i])

