import functools

class Solution:
    def getSum(self, nums: List[int]) -> int:
        MOD = 10**9 + 7

        # Helper function to calculate the sum of consecutive subsequences
        def get_sum_consecutive(nums):
            sum_array = [0] * len(nums)
            for i in range(1, len(nums)):
                if nums[i] - nums[i-1] == 1:
                    sum_array[i] = sum_array[i-1] + nums[i]
                elif nums[i] - nums[i-1] == -1:
                    sum_array[i] = sum_array[i-1] - nums[i]
            return sum_array

        # Calculate the sum of all possible consecutive subsequences
        sum_consecutive = functools.reduce(lambda x, y: x + y, get_sum_consecutive(nums))

        # Return the result modulo 10^9 + 7
        return sum_consecutive % MOD
