class Solution:
    def validSequence(self, word1: str, word2: str) -> List[int]:
        n = len(word1)
        dp = [[False] * n for _ in range(n)]

        # Initialize the dp matrix
        for i in range(n):
            dp[i][i] = True

        # Fill the dp matrix
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                if word1[i] == word2[i] and dp[i + 1][j - 1]:
                    dp[i][j] = True
                if word1[i] == word2[j] and dp[i + 1][j]:
                    dp[i][j] = True
                if word1[i] == word2[j] and word1[i + 1] == word2[j - 1] and dp[i + 2][j - 2]:
                    dp[i][j] = True

        # Find the lexicographically smallest valid sequence
        def find_valid_sequence(i, j):
            if i == j:
                return [i]
            if dp[i + 1][j - 1]:
                return [i] + find_valid_sequence(i + 1, j - 1)
            if dp[i + 1][j]:
                return [i] + find_valid_sequence(i + 1, j)
            if dp[i][j - 1]:
                return [j] + find_valid_sequence(i, j - 1)

        # Return the lexicographically smallest valid sequence
        return sorted(find_valid_sequence(0, n - 1))
