from collections import deque

class Node:
    def __init__(self, char, index):
        self.char = char
        self.index = index
        self.next = {}

class Trie:
    def __init__(self):
        self.root = Node(None, -1)

    def insert(self, word, index):
        node = self.root
        for char in word:
            if char not in node.next:
                node.next[char] = Node(char, len(node.next))
            node = node.next[char]
        node.next['#'] = Node(None, index)

    def find(self, word):
        node = self.root
        for char in word:
            if char in node.next:
                node = node.next[char]
            else:
                return False
        return '#' in node.next and node.next['#'].index == -1

class Solution:
    def validSequence(self, word1: str, word2: str) -> List[int]:
        trie = Trie()
        word2_len = len(word2)
        for i, char in enumerate(word1):
            trie.insert(word2[:i + 1], i)

        result = []
        queue = deque([word2_len - 1])

        while queue:
            current_index = queue.popleft()
            if trie.find(word2[:current_index + 1]):
                if current_index > 0:
                    result.append(current_index)
                queue.extend([current_index - 1] + [current_index - 2] * 2)

        return result
