class Solution:
    def minStartingIndex(self, s: str, pattern: str) -> int:
        # Initialize a dictionary to store the last seen positions of pattern characters
        last_seen = defaultdict(int)
        for char in pattern:
            last_seen[char] = 0

        # Find the last occurrence of each character in the pattern
        for char in pattern:
            last_seen[char] += 1

        # Use a sliding window to find the minimum starting index
        min_index = len(s)
        start = 0
        for end in range(len(s)):
            last_seen[s[end]] -= 1

            # If the character is in the pattern, remove its last occurrence
            if s[end] in last_seen:
                last_seen[s[end]] = max(last_seen[s[end]] - 1, 0)

            # If the window size is less than or equal to the pattern length, check for a match
            if end - start + 1 <= len(pattern):
                if all(last_seen[char] == 0 for char in pattern):
                    min_index = min(min_index, start)

            # If the character is not in the pattern, reset its last occurrence
            if s[start] not in last_seen:
                last_seen[s[start]] = 0
            start += 1

        return min_index if min_index < len(s) else -1
