from collections import defaultdict

class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowel_count = defaultdict(int)
        vowel_count['a'] = vowel_count['e'] = vowel_count['i'] = vowel_count['o'] = vowel_count['u'] = 0

        # Count the frequency of each vowel in the word
        for char in word:
            if char in vowel_count:
                vowel_count[char] += 1

        # Function to count substrings with k consonants
        def count_consonants(i, j):
            consonants = sum(vowel_count[char] for char in word[i:j+1] if char not in vowel_count)
            return j - i + 1 - consonants

        total_count = 0
        vowels = set(['a', 'e', 'i', 'o', 'u'])

        # Iterate over all possible substrings
        for i in range(len(word)):
            if sum(vowel_count[char] for char in word[i:i+1]) >= k + len(vowels): 
                for j in range(i + k + 1, len(word) + 1):
                    total_count += count_consonants(i, j)

        return total_count
