            method_invocations[b].add(a)

        # Mark the method k and all its descendants as suspicious
        suspicious_methods = {k}
        suspicious_descendants = {k}

        # Recursively mark all descendants of suspicious methods as suspicious
        def mark_descendants(method):
            if method not in suspicious_descendants:
                suspicious_descendants.add(method)
                for descendant in method_invocations[method]:
                    mark_descendants(descendant)

        mark_descendants(k)

        # Remove suspicious methods from the list
        remaining_methods = [i for i in range(n) if i not in suspicious_methods]

        return remaining_methods
