        # Create a graph where each node is a method and edges connect the suspicious methods
        graph = collections.defaultdict(set)
        for a, b in invocations:
            graph[a].add(b)
            graph[b].add(a)

        # Helper function to perform DFS and mark nodes as visited
        def dfs(node, visited):
            if node in visited:
                return False
            visited.add(node)
            for neighbor in graph[node]:
                if not dfs(neighbor, visited):
                    return False
            return True

        visited = set()
        suspicious_methods = 0

        # Find all suspicious methods by performing DFS
        for i in range(n):
            if not dfs(i, visited):
                suspicious_methods += 1

        # If there are suspicious methods, return all methods
        if suspicious_methods > 0:
            return list(range(n))

        # If all methods are suspicious, return an empty list
        return []
