class Solution:
    def constructGridLayout(self, n: int, edges: List[List[int]]) -> List[List[int]]:
        # Initialize adjacency list for each node
        adj_list = [[] for _ in range(n)]
        for u, v in edges:
            adj_list[u].append(v)
            adj_list[v].append(u)

        # Initialize the grid with all nodes
        grid = [[-1] * n for _ in range(n)]

        # BFS to color nodes with colors from 1 to n-1
        q = collections.deque([0])
        for i in range(n):
            if grid[i][0] == -1:
                grid[i][0] = i + 1
                while q:
                    u = q.popleft()
                    for v in adj_list[u]:
                        if grid[v][0] == -1:
                            grid[v][0] = grid[u][0] + 1
                            q.append(v)

        # BFS to color horizontal neighbors
        q = collections.deque([0])
        for i in range(n):
            if grid[i][0] == -1:
                grid[i][0] = i + 1
                while q:
                    u = q.popleft()
                    for v in adj_list[u]:
                        if grid[v][0] == -1:
                            grid[v][0] = grid[u][0] + 1
                            q.append(v)

        # BFS to color vertical neighbors
        q = collections.deque([0])
        for i in range(n):
            if grid[i][0] == -1:
                grid[i][0] = i + 1
                while q:
                    u = q.popleft()
                    for v in adj_list[u]:
                        if grid[v][0] == -1:
                            grid[v][0] = grid[u][0] + 1
                            q.append(v)

        # Assign the colors to the rest of the nodes
        for i in range(1, n):
            for j in range(n):
                if grid[i][j] == -1:
                    grid[i][j] = i + 1

