        if n <= 2:
            return 2**n

        # Initialize the DP table
        dp = [[0 for _ in range(n + 1)] for _ in range(x + 1)]

        # Base case: if there's only one stage, there's only one way to assign performers
        for j in range(n + 1):
            dp[1][j] = 1

        # Fill the DP table
        for i in range(2, x + 1):
            for j in range(n + 1):
                for k in range(j, min(j + i, n) + 1):
                    dp[i][j] = (dp[i][j] + dp[i - 1][k - 1] * (j - k + 1)) % MOD

        # Calculate the total number of ways to assign performers and bands
        total_ways = (dp[x][n] + dp[x - 1][n - 1] * (n - 1)) % MOD

        return total_ways
