class Solution:
    def kthLargestPerfectSubtree(self, root: Optional[TreeNode], k: int) -> int:
        def dfs(node):
            if not node:
                return 0, 0

            left_size, left_count = dfs(node.left)
            right_size, right_count = dfs(node.right)

            total_size = left_size + right_size + 1
            total_count = left_count + right_count + 1

            if total_size % 2 == 1:
                median = left_size + right_size + 1 // 2
            else:
                median = (left_size + right_size) // 2

            if median == k:
                return total_size, total_count

            if left_size > median:
                return total_size, total_count

            if right_size > median:
                k -= total_count - median
                return total_size - right_size, total_count - median

            k -= total_count - right_size
            return total_size - left_size, total_count - right_size

        return dfs(root)[1]
