class Solution:
    def minConnectedGroups(self, intervals: List[List[int]], k: int) -> int:
        # Create an array of intervals, each with a start, end, and a set of connected intervals
        intervals_with_groups = [Interval(*interval) for interval in intervals]

        # Sort intervals by their start time
        intervals_with_groups.sort(key=lambda x: x.start)

        added_intervals_count = 0
        current_group_count = 0

        for i, interval in enumerate(intervals_with_groups):
            # Check if adding the current interval would exceed the maximum length
            if added_intervals_count + len(interval.connected_to) > k:
                return current_group_count + 1

            # Add the current interval to all connected intervals
            for connected_interval in interval.connected_to:
                connected_interval.add_to_group(interval)

            # If the current group is not fully covered by the next interval, we need to add a new group
            if not intervals_with_groups[i + 1] or not intervals_with_groups[i + 1].start <= interval.end:
                current_group_count += 1

        return current_group_count
