class Solution:
    def minOperations(self, nums: List[int]) -> int:
        # Dictionary to store the count of numbers divisible by each number
        divisible_counts = {}

        # Dictionary to store the count of numbers reduced to 1 by a single operation
        single_operation_counts = {}

        # Dictionary to store the count of numbers that need to be reduced further
        further_reduction_counts = {}

        # Counter for the number of operations
        operations = 0

        # Iterate through each number in the array
        for num in nums:
            # Check if the number is already in the divisible_counts dictionary
            if num in divisible_counts:
                # Check if the number is already in the single_operation_counts dictionary
                if num in single_operation_counts:
                    # Update the count of numbers that need to be reduced further
                    further_reduction_counts[num] = single_operation_counts[num]
                    del single_operation_counts[num]
                else:
                    # Update the count of numbers reduced to 1 by a single operation
                    single_operation_counts[num] += divisible_counts[num]
                    del divisible_counts[num]
            else:
                # If the number is not in divisible_counts, add it with a count of 1
                divisible_counts[num] = 1

            # Check if the number is 1, which means it can be reduced to 1 by a single operation
            if num == 1:
                # Update the count of numbers that need to be reduced further
                further_reduction_counts[num] = 0
                continue

            # If the number is not 1, check its proper divisors and update counts accordingly
            for divisor in range(2, int(num**0.5) + 1):
                if num % divisor == 0:
                    if divisor in divisible_counts:
                        divisible_counts[divisor] += 1
                    else:
                        divisible_counts[divisor] = 1
                    if num // divisor in divisible_counts:
                        divisible_counts[num // divisor] += 1
                    else:
                        divisible_counts[num // divisor] = 1
                    break

            # If the number is not reduced to 1, add it to the further_reduction_counts
            if num in divisible_counts:
                further_reduction_counts[num] = divisible_counts[num]

            # Increment the operations counter
            operations += 1

        # If there are any numbers left in divisible_counts or further_reduction_counts, return -1
        if divisible_counts or further_reduction_counts:
            return -1

        # Return the total number of operations
        return operations
