from collections import defaultdict

def findSubtreeSizes(parent, s):
    # Create an adjacency list to represent the tree
    tree = defaultdict(list)
    for i in range(1, len(parent)):
        tree[parent[i]].append(i)

    # Function to find the closest ancestor with the same letter
    def find_closest_ancestor(node, closest_ancestor=None):
        if node in closest_ancestor:
            return closest_ancestor[node]
        for child in tree[node]:
            closest = find_closest_ancestor(child, closest)
            if closest is not None:
                return closest
        return closest

    # Find the closest ancestor for each node
    closest_ancestors = {}
    for node in range(len(parent)):
        closest_ancestors[node] = find_closest_ancestor(node)

    # Helper function to calculate subtree sizes
    def calculate_subtree_sizes(node, parent_size=1, depth=0):
        if node in closest_ancestors:
            parent_size += 1
            return calculate_subtree_sizes(closest_ancestors[node], parent_size, depth + 1)
        return parent_size

    # Calculate the size of each subtree
    subtree_sizes = [1] * len(parent)
    for node in range(len(parent)):
        subtree_sizes[node] = calculate_subtree_sizes(node)

    # Return the sizes of the subtrees
    return subtree_sizes
