    def lengthAfterTransformations(self, s: str, t: int, nums: List[int]) -> int:
        # Create a dictionary to map each character to its next N characters
        next_chars = {chr(i): chr(i + n) for i, n in enumerate(nums)}
        next_chars.update({chr(i + 26): chr(i + 1) for i in range(26)})

        # Create a dictionary to store the frequency of each character in the string
        char_count = defaultdict(int)
        for char in s:
            char_count[char] += 1

        # Initialize the count of transformations and the current string length
        count = 0
        current_str = ''

        # Perform transformations
        while count < t:
            for char, freq in char_count.items():
                if freq > 0:
                    # Replace the character with its next N characters
                    next_chars_char = next_chars.get(char)
                    if next_chars_char:
                        current_str += next_chars_char
                        freq += 1
                    else:
