    def countOfArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7

        @lru_cache(maxsize=None)
        def dp(i, j, k):
            if j > 0:
                # If the current element is even, we can choose any number as it will make the overall number even
                even = (i - 1) % 2
                odd = i % 2
                return (dp(i + 1, j - 1, k) + even * dp(i + 1, j - 1, k - 1)) % MOD
            else:
                # If the current element is odd, we can choose any number except the one that makes the overall number odd
                odd = (i - 1) % 2
                return odd * dp(i + 1, j, k - 1) % MOD

        res = 0
        for i in range(1, m + 1):
            res += dp(1, k, k) * (m // i) % MOD

        return res % MOD
