                return 1 if even_sum == k and odd_sum == 0 else 0
            res = 0
            for num in range(1, min(m, i + 2) + 1):
                if not used and ((num % 2 == 1) == (num % 2 != 1)):
                    continue
                res = (res + dfs(i + 1, even_sum + (num % 2), odd_sum + 1 if num % 2 else -1, used or num % 2 == 0)) % MOD
