from collections import deque

class Room:
    def __init__(self, time, row, col):
        self.time = time
        self.row = row
        self.col = col

class Solution:
    def minTimeToReach(self, moveTime: List[List[int]]) -> int:
        n = len(moveTime)
        m = len(moveTime[0])
        q = deque([Room(0, 0, 0)])
        visited = set([(0, 0)])

        while q:
            current_time, current_row, current_col = q.popleft()

            if current_row == n - 1 and current_col == m - 1:
                return current_time

            for r in range(n):
                for c in range(m):
                    if (r, c) not in visited:
                        next_time = current_time + moveTime[r][c]
                        if current_row == r and current_col == c:
                            next_time += 1
                        if current_row == r and current_col == c + 1:
                            next_time += 2
                        if current_row == r + 1 and current_col == c:
                            next_time += 2
                        if current_row == r + 1 and current_col == c + 1:
                            next_time += 1
                        if (r, c) not in visited and next_time < moveTime[r][c]:
                            visited.add((r, c))
                            q.append(Room(next_time, r, c))

        return -1
