class Solution:
    def countBalancedPermutations(self, num: str) -> int:
        MOD = 10**9 + 7

        # Helper function to calculate the sum of digits at even and odd indices
        def digit_sums(index):
            even_sum = 0
            odd_sum = 0
            for i in range(index):
                if i % 2 == 0:
                    even_sum += int(num[i])
                else:
                    odd_sum += int(num[i])
            return even_sum, odd_sum

        # Helper function to recursively count balanced permutations
        def count_balanced_permutations(index, memo):
            if index == len(num):
                return 1
            if index > len(num):
                return 0

            if (index, index) in memo:
                return memo[(index, index)]

            even_sum, odd_sum = digit_sums(index)
            count = 0
            if even_sum == odd_sum:
                count += count_balanced_permutations(index + 1, memo)

            for i in range(index, len(num)):
                if num[i] in ['1', '2', '3', '4', '5', '6', '7', '8', '9']:
                    if even_sum + int(num[i]) > odd_sum or odd_sum + int(num[i]) > even_sum:
                        break
                    count += count_balanced_permutations(i + 1, memo)

            memo[(index, index)] = count
            return count

        memo = {}
        return count_balanced_permutations(0, memo) % MOD
