class Solution:
    def smallestNumber(self, n: int, t: int) -> int:
        # If n is 1, it's the only possible solution
        if n == 1:
            return 1

        digits = [int(d) for d in str(n)]
        product = 1
        first_zero = None

        # Find the first non-zero digit and calculate product of the digits
        for i, d in enumerate(digits):
            if d == 0:
                first_zero = i
                break
            product *= d

        # If no non-zero digit is found, return 1 if n is 1
        if first_zero is None:
            if n == 1:
                return 1
            else:
                return 1

        # If t is 1, return n as any number with a product of digits divisible by 1 is valid
        if t == 1:
            return n

        # If the product of the digits is not divisible by t, return the next largest number
        if product % t != 0:
            return self.nextLargerNumber(digits, product, t, first_zero)

        # If the product is already divisible by t, return the number as it is
        return n

    def nextLargerNumber(self, digits, product, t, first_zero):
        # Find the first digit that is greater than the first non-zero digit
        for i in range(first_zero + 1, len(digits)):
            if digits[i] > digits[first_zero]:
                break

        # Swap the found digit with the first non-zero digit
        digits[first_zero], digits[i] = digits[i], digits[first_zero]

        # Sort the remaining digits in ascending order
        digits[first_zero + 1:] = sorted(digits[first_zero + 1:])

        # Calculate the new product of the digits
        new_product = 1
        for d in digits:
            new_product *= d

        # If the new product is divisible by t, return the new number
        if new_product % t == 0:
            return int("".join(map(str, digits)))

        # If not, return -1 (indicating an error in the problem statement)
        return -1
