import heapq

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        heap = []

        # Process the queries in order
        for l, r, val in queries:
            # Decrease the elements in the range [l, r]
            for i in range(l, r + 1):
                nums[i] -= val

            # Add elements that were increased in the heap
            for i in range(l, r + 1):
                heapq.heappush(heap, nums[i])

            # Remove elements that were decreased from the heap
            for i in range(l, r + 1):
                heapq.heappop(heap)

            # Check if the current range is a Zero Array
            if all(x == 0 for x in nums[l:r + 1]):
                return 0

        # If no zero array is found after all queries, return -1
        return -1
