        count = 0

        for row in range(m):
            for col in range(n):
                # Check if the current cell's value is less than or equal to k
                if grid[row][col] <= k:
                    # Count the number of submatrices that can be formed starting from the current cell
                    count += (row + 1) * (col + 1) - ((row + 1) * col) - ((row) * (col + 1)) + (row * col)

