from typing import List
from collections import defaultdict

class MaxHeap:
    def __init__(self, arr, compare):
        self.arr = arr
        self.compare = compare
        self.heapify()

    def heapify(self):
        n = len(self.arr)
        for i in range(n // 2 - 1, -1, -1):
            self._heapify(i, n)

    def _heapify(self, i, n):
        root = i
        left = 2 * i + 1
        right = 2 * i + 2

        if left < n and self.compare(self.arr[root], self.arr[left]):
            root = left
        if right < n and self.compare(self.arr[root], self.arr[right]):
            root = right

        if root != i:
            self.arr[root], self.arr[i] = self.arr[i], self.arr[root]
            self._heapify(root, n)

    def push(self, val):
        self.arr.append(val)
        self._heapify(len(self.arr) - 1, len(self.arr))

    def pop(self):
        self.arr[0], self.arr[-1] = self.arr[-1], self.arr[0]
        popped = self.arr.pop()
        self._heapify(0, len(self.arr))
        return popped

class Solution:
    def countSubmatrices(self, grid: List[List[int]], k: int) -> int:
        max_heap = MaxHeap([], lambda x, y: x > y)
        count = 0

        for row in grid:
            for cell in row:
                if cell <= k:
                    max_heap.push(cell)
                    count += 1
                else:
                    if max_heap.arr[0] <= cell:
                        count -= 1
                    while max_heap.arr[0] > cell:
                        max_heap.pop()
                    count += 1

        return count
```

