from typing import List

class Solution:
    def countSubmatrices(self, grid: List[List[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])
        count = 0

        for r in range(m):
            for c in range(n):
                # If the current element is greater than k, continue to the next cell
                if grid[r][c] > k:
                    break
                # If the current cell is the starting point of a submatrix
                if r == 0 or c == 0 or grid[r-1][c] > k or grid[r][c-1] > k:
                    count += 1
                # Expand the submatrix by moving up and left if the current cell is greater than k
                while r + 1 < m and grid[r + 1][c] <= k:
                    r += 1
                while c + 1 < n and grid[r][c + 1] <= k:
                    c += 1
                # Count the submatrix with the maximum element less than or equal to k
                count += (r - r + 1) * (c - c + 1)

        return count
