class Solution:
    def canAliceWin(self, n: int) -> bool:
        # If the number of stones is less than 10, Alice can always win
        if n < 10:
            return True

        # Store the results of previous games to avoid redundant calculations
        memo = [False] * (n + 1)

        # Base cases for when Alice or Bob has no stones left
        memo[0] = memo[1] = True

        # Fill the memoization array
        for i in range(2, n + 1):
            # Alice's turn
            if i >= 10:
                memo[i] = i - 10 < 1
            else:
                memo[i] = memo[i - 1]

        return memo[n]
