from collections import defaultdict

class Solution:
    def shiftDistance(self, s: str, t: str, nextCost: List[int], previousCost: List[int]) -> int:
        # Create a dictionary to map each letter to its indices
        letter_indices = defaultdict(list)
        for i, c in enumerate(s):
            letter_indices[c].append(i)

        # Create a dictionary to store the current costs for shifting letters
        current_costs = {}
        for i in range(26):
            current_costs[chr(97 + i)] = 0

        # Calculate the initial costs for shifting each letter in s to match the corresponding letter in t
        for i, (s_char, t_char) in enumerate(zip(s, t)):
            current_costs[s_char] = i * (nextCost[ord(t_char) - ord('a')] if t_char != 'z' else 0)
            current_costs[t_char] = i * (previousCost[ord(s_char) - ord('a')] if s_char != 'a' else 0)

        # Find the minimum shift distance by shifting each character in a single pass
        min_shift_distance = float('inf')
        for i, s_char in enumerate(s):
            min_shift_distance = min(min_shift_distance, sum(current_costs[char] for char in letter_indices[s_char]))
        return min_shift_distance
