from collections import defaultdict

class Solution:
    def shiftDistance(self, s: str, t: str, nextCost: List[int], previousCost: List[int]) -> int:
        # Create a dictionary to map each letter to its index in the alphabet
        alphabet = {chr(i): i for i in range(97, 123)}

        # Calculate the total cost for shifting s[i] to t[i]
        def cost(s, t, i):
            diff = alphabet[t[i]] - alphabet[s[i]]
            if diff > 0:
                return min(diff, 26 - diff) * nextCost[diff]
            else:
                return min(26 - abs(diff), diff) * previousCost[-diff - 1]

        # Initialize the total cost
        total_cost = 0

        # Iterate through the strings to compute the total cost
        for i in range(len(s)):
            total_cost += cost(s, t, i)

        return total_cost
