class Solution:
    def maxCollectedFruits(self, fruits: List[List[int]]) -> int:
        n = len(fruits)
        dp = [[[0] * n for _ in range(n)] for _ in range(n)]

        # Base case: the first child starts from the corner rooms
        for i in range(n):
            for j in range(n):
                if i == 0 and j == 0:
                    dp[i][j][0] = fruits[i][j]
                elif i == 0 and j == n - 1:
                    dp[i][j][0] = fruits[i][j - 1]
                elif i == n - 1 and j == 0:
                    dp[i][j][0] = fruits[i - 1][j]

        # Calculate maximum fruit collection for each child
        for k in range(1, n):
            for i in range(n):
                for j in range(n):
                    for direction in [(1, 0), (0, 1), (1, 1)]:
                        ni, nj = i + direction[0], j + direction[1]
                        if 0 <= ni < n and 0 <= nj < n:
                            dp[i][j][k] = max(dp[i][j][k], dp[ni][nj][k - 1] + fruits[i][j])

        # Return the maximum number of fruits collected
        return max(dp[i][j][n - 1] for i in range(n) for j in range(n))
