class Solution:
    def minimumSumSubarray(self, nums: List[int], l: int, r: int) -> int:
        min_sum = math.inf  # Initialize minimum sum to infinity

        # Find the minimum sum subarray of size greater than or equal to l
        for i in range(l-1, len(nums)):
            for j in range(i+1, len(nums)+1):
                subarray = nums[i:j]
                if sum(subarray) > 0 and len(subarray) >= l and len(subarray) <= r and sum(subarray) < min_sum:
                    min_sum = sum(subarray)

        # Return the minimum sum found, or -1 if no such subarray exists
        return min_sum if min_sum != math.inf else -1
