class Solution:
    def isPossibleToRearrange(self, s: str, t: str, k: int) -> bool:
        # Count the frequency of each character in both strings
        s_freq = Counter(s)
        t_freq = Counter(t)

        # Check if the total length of the string is divisible by k
        if len(s) % k != 0:
            return False

        # Ensure all characters in s and t are the same
        if s_freq != t_freq:
            return False

        # Check if the total number of characters that need to be split is divisible by k
        split_chars = sum(s_freq[char] for char in s_freq if s_freq[char] > 0)
        if split_chars % k != 0:
            return False

        # Check if there are enough characters to be split and rearranged
        for char, count in s_freq.items():
            if count > 0 and count >= k:
                total_chars = 0
                for i in range(len(s), 0, -k):
                    total_chars += s_freq[char] if i >= split_chars else 0
                    if total_chars >= k:
                        return True
        return False
