import heapq

class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        # Initialize a max heap for the first operation
        heap = []
        for i, num in enumerate(nums):
            heapq.heappush(heap, (num, i))

        result = 0

        # Perform the first operation up to op1 times
        for _ in range(min(k, op1)):
            num, index = heapq.heappop(heap)
            result += num
            nums[index] = 0  # Mark as used

        # Perform the second operation up to op2 times
        for _ in range(min(k, op2)):
            num, index = heapq.heappop(heap)
            if num >= k:
                result += num - k
                nums[index] = k  # Mark as used
            else:
                result += num
                nums[index] = 0  # Mark as used

        # Merge all remaining elements that are not zero
        for i in range(len(nums)):
            if nums[i] != 0:
                result += nums[i]
                nums[i] = 0

        return result
