class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        total_sum = sum(nums)
        nums.sort()

        # Check if we can reduce the sum by applying the operations
        if total_sum < k * len(nums):
            return total_sum

        # Apply the operations starting from the largest numbers to minimize the sum
        for i in range(len(nums) - 1, -1, -1):
            if op1 > 0:
                nums[i] //= 2
                op1 -= 1
            if op2 > 0 and nums[i] >= k:
                nums[i] -= k
                op2 -= 1

        return sum(nums)
