class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        # Sort the array to consider the smallest elements first
        nums.sort()

        min_sum = 0
        ops_left = 0

        # Apply Operation 1 as many times as possible
        for i in range(len(nums)):
            if ops_left >= op1:
                nums[i] //= 2
                ops_left -= 1
            else:
                break

        # Apply Operation 2 as many times as possible
        for i in range(len(nums)):
            if ops_left >= op2 and nums[i] >= k:
                nums[i] -= k
                ops_left -= 1

        # Sum the elements of the modified array
        for num in nums:
            min_sum += num

        return min_sum
