from collections import defaultdict

class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        # Build the graph
        graph = defaultdict(list)
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        # Initialize variables
        total_weight = 0
        max_weight = 0
        removable_edges = 0

        # Helper function to perform DFS and calculate weights
        def dfs(node, parent, weight):
            nonlocal total_weight, removable_edges, max_weight
            max_weight = max(max_weight, weight)
            removable_edges += 1
            for neighbor, w in graph[node]:
                if neighbor != parent:
                    dfs(neighbor, node, weight + w)

        # Perform DFS from each node
        for node in range(len(graph)):
            if removable_edges < k:
                dfs(node, -1, 0)

        # Calculate the maximum possible sum of weights for the remaining edges
        return total_weight + max_weight * (k - removable_edges)
```

