class Solution:
    def smallestNumber(self, n: int) -> int:
        # If n is 1, the smallest number is 1
        if n == 1:
            return 1

        # Start from the highest bit and go downwards
        for i in range(n.bit_length(), 0, -1):
            # Check if the ith bit is set
            if n & (1 << i):
                # Shift all bits to the right and set the ith bit
                return n | (1 << i)

        # If no set bits are found, return n
        return n
