        # Helper function to calculate subtree sizes
        def subtree_size(node, graph, seen):
            if node in seen:
                return 0
            seen.add(node)
            size = 1
            for neighbor in graph[node]:
                size += subtree_size(neighbor, graph, seen)
            return size

        # Helper function to find the maximum target nodes for a given edge
        def max_target_nodes(edge, graph, seen):
            if edge[0] in seen or edge[1] in seen:
                return 0
            seen.add(edge[0])
            seen.add(edge[1])
            return 1 + max(subtree_size(edge[0], graph, seen), subtree_size(edge[1], graph, seen))

        # Create adjacency lists for both trees
        graph1 = [[] for _ in range(len(edges1) + 1)]
        graph2 = [[] for _ in range(len(edges2) + 1)]

        for edge1, edge2 in zip(edges1, edges2):
            graph1[edge1[0]].append(edge2[1])
            graph1[edge1[1]].append(edge2[1])
            graph2[edge2[0]].append(edge1[1])
            graph2[edge2[1]].append(edge1[1])

