        answer = [i for i in range(len(edges1) + 1)]

        # For each node in the first tree
        for node1 in range(1, len(edges1) + 1):
            # For each node in the second tree
            for node2 in range(1, len(edges2) + 1):
                # If there are no edges connecting the nodes
                if not graph1[node1] and not graph2[node2]:
                    answer[node1 - 1] = k + 1
                # If the nodes are connected in both trees
                elif graph1[node1] and graph2[node2] and len(graph1[node1]) <= k and len(graph2[node2]) <= k:
                    answer[node1 - 1] = max_target_nodes([node1, node2], graph1, set()) + max_target_nodes([node1, node2], graph2, set())

