class Solution:
    def maxTargetNodes(self, edges1: List[List[int]], edges2: List[List[int]]) -> List[int]:
        def dfs(src, dst, visited, path, data):
            if src == dst:
                return True
            visited[src] = True
            for neighbor in data[src]:
                if not visited[neighbor]:
                    if dfs(neighbor, dst, visited, path + [neighbor], data):
                        return True
            return False

        def findPaths(src, dst, visited, path, data):
            if src == dst:
                return True
            visited[src] = True
            for neighbor in data[src]:
                if not visited[neighbor]:
                    if findPaths(neighbor, dst, visited, path + [neighbor], data):
                        return True
            return False

        n = len(edges1) + 1
        m = len(edges2) + 1

        # Construct the trees
        tree1 = [[] for _ in range(n)]
        tree2 = [[] for _ in range(m)]

        for edge in edges1:
            tree1[edge[0]].append(edge[1])
            tree1[edge[1]].append(edge[0])

        for edge in edges2:
            tree2[edge[0]].append(edge[1])
            tree2[edge[1]].append(edge[0])

        # Find all paths from src to dst
        visited = [False] * n
        paths1 = []
        for src in range(n):
            if dfs(src, n - 1, visited, [], tree1):
                paths1.append(src)

        visited = [False] * m
        paths2 = []
        for src in range(m):
            if findPaths(src, m - 1, visited, [], tree2):
                paths2.append(src)

        # Calculate the maximum possible number of nodes that are target to node i of the first tree
        result = [0] * n
        for i in range(n):
            for path in paths1:
                if dfs(path, i, [False] * n, [], tree2):
                    result[i] += 1
        return result
