            if i == n:
                return time
            if time < dp[i]:
                return dp[i]
            if x == k and i == n:
                dp[i] = time + 1
                return time + 1
            if dp[i] != 1000000000:
                return dp[i]

            for j in range(i, n):
                if strength[j] > x:
                    break
                x *= k
                time += 1
                dp[j + 1] = min(dp[j + 1], dfs(j + 1, x, time + 1))
            dp[i] = min(dp[i], dfs(i + 1, x, time))
            return dp[i]

        return dfs(0, 1, 0)
