        if n == m:
            return 0

        # If n is not a prime number, it can be transformed into m
        if not self.is_prime(n):
            return self.cost_to_transform(n, m)

        # If n is a prime number, we need to find a way to transform it into m
        # This involves finding the minimum cost by incrementing the largest digit to match m
        diff = abs(n - m)
        largest_digit_in_n = max(n)
        largest_index_in_n = n.index(largest_digit_in_n)
        cost = 0

        # If n is smaller than m, we need to increment the smallest digit
        if n < m:
            cost += diff // 10
            largest_digit_in_n += 1
            largest_index_in_n = n.index(largest_digit_in_n)
            diff %= 10

        # If the largest digit in n is not 9, we can increment it to match m
        if largest_digit_in_n != 9:
            cost += diff
            largest_digit_in_n = 9

        # If the largest digit is 9, we can only decrement the smallest digit
        # if it is not 0
        if largest_digit_in_n == 9 and n[largest_index_in_n] != 0:
            cost += diff

        return cost

    def cost_to_transform(self, n, m):
        cost = 0
        while n < m:
            cost += 1
            n += 1
        return cost

    def is_prime(self, num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True
