from typing import List

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.components = n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        rootX = self.find(x)
        rootY = self.find(y)
        if rootX == rootY:
            return
        if self.size[rootX] > self.size[rootY]:
            rootX, rootY = rootY, rootX
        self.parent[rootX] = rootY
        self.size[rootY] += self.size[rootX]
        self.components -= 1

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        # Create UnionFind instance
        uf = UnionFind(len(nums))
        for i, num in enumerate(nums):
            # Union all nodes with their multiples
            for multiple in range(2, int(threshold**0.5) + 1):
                if multiple**2 > threshold:
                    break
                if multiple * multiple <= threshold:
                    continue
                if not uf.union(i, i + multiple):
                    break
                if not uf.union(i, i + multiple**2):
                    break
                if not uf.union(i, i + multiple * multiple):
                    break

        return uf.components
```

