import itertools

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        # Function to calculate the distance between two points
        def distance(p1, p2):
            return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

        # Function to check if four points form a rectangle
        def is_rectangle(p1, p2, p3, p4):
            # Check if all four points are distinct
            if p1 == p2 or p1 == p3 or p1 == p4 or p2 == p3 or p2 == p4 or p3 == p4:
                return False

            # Sort points by x and y coordinates
            points = sorted([p1, p2, p3, p4], key=lambda p: (p[0], p[1]))

            # Check vertical distances
            if distance(points[0], points[1]) != distance(points[2], points[3]):
                return False

            # Check horizontal distances
            if distance(points[1], points[2]) != distance(points[3], points[0]):
                return False

            # Check that no point lies inside or on the border of the rectangle
            for i in range(1, 3):
                if distance(points[i-1], points[i]) + distance(points[i], points[i+1]) <= distance(points[i-1], points[i+1]):
                    return False

            return True

        # Generate all unique quadruples of points
        quadruples = itertools.combinations(points, 4)

        # Try to find a rectangle area for each quadruple
        max_area = -1
        for quadruple in quadruples:
            if is_rectangle(*quadruple):
                area = distance(quadruple[0], quadruple[1]) * distance(quadruple[2], quadruple[3])
                max_area = max(max_area, area)

        return max_area
