        current_sum = 0
        count = {}

        for i, num in enumerate(nums):
            current_sum += num

            if current_sum % k == 0 and i >= k:
                # Check if this window is the maximum so far
                if i >= k:
                    max_sum = max(max_sum, current_sum)

                # Remove the element that's going out of the window
                current_sum -= nums[i - k]

            # Check if this sum is seen before
            if current_sum % k == 0:
                if current_sum in count:
                    max_sum = max(max_sum, current_sum + count[current_sum])
                count[current_sum] = max_sum

        return max_sum
