            for x1, y1, x2, y2 in rectangles:
                if x1 <= offset <= x2 and y1 <= offset <= y2:
                    cnt[x1] += 1
                    cnt[x2 + 1] -= 1
                if y1 <= offset <= y2:
                    last += 1
                if y1 == offset and y2 == offset:
                    last -= 1
                if last == 0:
                    last = 1
                if last == offset:
                    cnt[last] -= 1
                    if cnt[last] < 0:
                        return False
