        total = 0

        for i in range(1, 5):
            if i not in freq:
                continue
            if freq[i] > 1:
                continue
            middleIndex = maxFreqIndex(freq)
            if nums[middleIndex] == i:
                total += generateSubsequences(4, freq)
            else:
                mode = maxFreqIndex(freq)
                if nums[middleIndex] != mode:
                    total += generateSubsequences(4, freq)
                elif freq[i] > 2:
                    total += (freq[i] - 1) * generateSubsequences(3, freq)

