class Solution:
    def minimumOperations(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        operations_needed = m * n

        # Create a max-heap with the first element of each column
        column_heap = []
        for col in range(n):
            for row in range(m):
                heapq.heappush(column_heap, (-grid[row][col], row, col))

        # Process the heap until all columns are strictly increasing
        while column_heap:
            val, r, c = heapq.heappop(column_heap)
            if val < 0:
                # Increment the value to make the column strictly increasing
                val += 1
                heapq.heappush(column_heap, (val, r, c))
            else:
                # Break if the column is already strictly increasing
                break

        return operations_needed - len(column_heap)
