        # Split the word into numFriends segments
        for i in range(numFriends):
            segment = word[i::numFriends]
            segments[i].append(segment)

        # Sort segments in reverse lexicographical order
        for i in range(numFriends):
            segments[i] = sorted(segments[i], reverse=True)

        # Find the lexicographically largest segment
        max_segment = ""
        for segment in segments.values():
            if len(segment) > len(max_segment):
                max_segment = segment

        # Join the segments to form the final answer
        return "".join(max_segment)
