from math import comb

class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7

        # Base cases for k = 0 and k = 1
        if k == 0:
            return 1
        if k == 1:
            return comb(m, n-1)

        # Recursive function to calculate good arrays
        def countGood(arr, last, count):
            if len(arr) == n:
                if count == k:
                    return 1
                else:
                    return 0
            res = 0
            for i in range(last, m + 1):
                res += countGood(arr + [i], i, count + (arr[-1] == i))
            return res % MOD

        return countGood([], 0, 0)
