class Solution:
    def hasMatch(self, s: str, p: str) -> bool:
        # Helper function to check if a pattern match is possible
        def backtrack(i, j):
            if i == len(s) and j == len(p):
                return True
            if i == len(s):
                return p[j:].count("*") == j
            if j == len(p):
                return s[i:].count("*") == i

            # Check for '*' at the current position
            if p[j] == '*':
                # Try replacing '*' with a single character
                if s[i] == p[j] or p[j] == '?':
                    return backtrack(i, j + 1) or backtrack(i + 1, j)
                # Skip the '*' character
                return backtrack(i, j + 1)
            else:
                # Directly check if the current characters match
                return s[i] == p[j] or p[j] == '?' and s[i] != '*' and s[i + 1:] == s[i] * (p.count('*') - p[j:].count('*') - 1)

        return backtrack(0, 0)
