import heapq

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Initialize adjacency list
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w))

        # Max heap for max weights
        max_heap = []
        for i in range(n):
            if len(adj[i]) <= threshold:
                heapq.heappush(max_heap, (adj[i][0][1], i))

        # Check if it's possible to reach all nodes
        if not max_heap:
            return -1

        # Initialize result with the minimum possible maximum weight
        result = max_heap[0][0]

        # Function to check if a node can be reached from all others
        def can_reach(node, max_weights):
            for w, next_node in max_weights:
                if node not in adj[next_node] or w > result:
                    return False
            return True

        # Try removing edges to minimize max weight
        while max_heap:
            max_weight, node = heapq.heappop(max_heap)
            new_max_heap = []
            for w, next_node in max_heap:
                if node in adj[next_node]:
                    if w > result:
                        new_max_heap.append((w, next_node))
                else:
                    heapq.heappush(new_max_heap, (w, next_node))

            # If we can reach all nodes with the new max weights
            if can_reach(node, new_max_heap):
                result = max(max_weight, result)
                for w, next_node in new_max_heap:
                    heapq.heappush(max_heap, (w, next_node))

        return result
