class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        min_heap = []

        # Add the first k elements to the min-heap
        for i in range(k):
            heapq.heappush(min_heap, -nums[i])

        operations = 0

        # If the minimum element in the heap is less than 0, we need to decrease it
        if min_heap and -min_heap[0] < 0:
            operations += abs(-min_heap[0])
            heapq.heappush(min_heap, -1)

        # Process the remaining elements
        for i in range(k, len(nums)):
            # If the element to be added is less than the current minimum, we need to increase it
            if nums[i] < min_heap[0]:
                heapq.heappush(min_heap, -1)

            # If the element to be removed is greater than the current minimum, we need to decrease it
            if nums[i - k] > min_heap[0]:
                heapq.heappop(min_heap)

            # Push the new element to the heap
            heapq.heappush(min_heap, -nums[i])

        # Calculate the total operations needed
        return operations + (len(nums) - k) * abs(min_heap[0])
