        max_length = 0
        min_nodes = float('inf')
        for node in range(len(nums)):
            if nums[node] != -1:
                max_length = max(max_length, dfs(node, node, 0, min_nodes))
                min_nodes = min(min_nodes, dfs(node, node, 0, min_nodes))
        return [max_length, min_nodes]
