class Solution:
    def minMaxSums(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7

        def find_min_max(s):
            """Find the minimum and maximum elements in the subsequence s."""
            min_val = max_val = s[0]
            for num in s[1:]:
                if num < min_val:
                    min_val = num
                if num > max_val:
                    max_val = num
            return min_val, max_val

        n = len(nums)
        prefix_max, prefix_min = [0] * (n + 1), [0] * (n + 1)
        suffix_max, suffix_min = [0] * (n + 1), [0] * (n + 1)

        for i in range(n):
            prefix_max[i] = prefix_max[i - 1] + nums[i] if i > 0 else nums[i]
            prefix_min[i] = prefix_min[i - 1] + nums[i] if i > 0 else nums[i]

        for i in range(n - 1, -1, -1):
            suffix_max[i] = suffix_max[i + 1] + nums[i] if i < n - 1 else nums[i]
            suffix_min[i] = suffix_min[i + 1] + nums[i] if i < n - 1 else nums[i]

        total_sum = 0
        for i in range(n):
            for j in range(i + 1, min(i + k + 1, n + 1)):
                min_val, max_val = find_min_max(nums[i:j + 1])
                total_sum += (prefix_max[j] - prefix_max[i] + suffix_max[j] - suffix_max[i]) * (max_val - min_val)

        return total_sum % MOD
