                    result.append(path)
                return
            for char in words[index]:
                if char not in path:
                    path.append(char)
                    backtrack(index + 1, path)
                    path.pop()

        # Initialize result with all possible single-character sequences
        result = [[0] * 26 for _ in range(26)]

        for word in words:
