from typing import List

def supersequences(words: List[str]) -> List[List[int]]:
    # Helper function to calculate the LCS length of two strings
    def lcs_length(x: str, y: str) -> int:
        m, n = len(x), len(y)
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if x[i - 1] == y[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 1
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

        return dp[m][n]

    # Helper function to construct the LCS string
    def construct_lcs(x: str, y: str, lcs: str) -> str:
        m, n = len(x), len(y)
        i, j = m - 1, n - 1

        result = []
        while i >= 0 and j >= 0:
            if x[i] == y[j]:
                result.append(x[i])
                i -= 1
                j -= 1
            elif dp[i][j] == dp[i + 1][j]:
                i -= 1
            else:
                j -= 1

        return "".join(result[::-1])

    # Helper function to calculate the frequency of characters in a string
    def char_frequency(s: str) -> List[int]:
        return [0] * 26

    # Calculate the frequency of characters in each string
    freqs = [char_frequency(word) for word in words]

    # Calculate the LCS length for all pairs of strings
    lcs_lengths = []
    for i in range(len(words)):
        for j in range(i + 1, len(words)):
            lcs_lengths.append(lcs_length(words[i], words[j]))

    # Sort the LCS lengths to minimize the SCSs
    lcs_lengths.sort()

    # Initialize the SCS frequencies
    scs_freqs = [freqs[i] for i in range(26)]

    # Construct the SCS strings
    for lcs_length in lcs_lengths:
        for i in range(len(words)):
            for j in range(i + 1, len(words)):
                if lcs_length == lcs_length(words[i], words[j]):
                    scs_freqs[ord(words[i][0]) - ord('a')] += freqs[i][ord(words[i][0]) - ord('a')]
                    scs_freqs[ord(words[j][0]) - ord('a')] += freqs[j][ord(words[j][0]) - ord('a')]
                    scs_freqs[ord(words[i][1]) - ord('a')] += freqs[i][ord(words[i][1]) - ord('a')]
                    scs_freqs[ord(words[j][1]) - ord('a')] += freqs[j][ord(words[j][1]) - ord('a')]

    return scs_freqs
