from typing import List, Tuple

class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        # Helper function to check if a character can be replaced to make the caption good
        def can_be_good(char: str, prev: str) -> bool:
            if prev == 'a':
                return char in 'bcdfghjklmnpqrstvwxyz'
            elif prev == 'z':
                return char in 'bcdfghjklmnpqrstvwxyz'
            return False

        # Helper function to generate possible good captions from a state
        def generate_good_captions(state: str) -> List[str]:
            good_captions = [state]
            for i, char in enumerate(state):
                if can_be_good(char, state[i - 1]):
                    new_state = state[:i] + char + state[i + 1:]
                    good_captions.extend(generate_good_captions(new_state))
            return good_captions

        # Helper function to perform transitions between states
        def perform_transitions(state: str) -> List[Tuple[str, int]]:
            transitions = []
            for i, char in enumerate(state):
                if can_be_good(char, state[i - 1]):
                    new_state = state[:i] + char + state[i + 1:]
                    transitions.append((new_state, -1))
                if can_be_good(char, state[i + 1]):
                    new_state = state[:i] + char + state[i + 1:]
                    transitions.append((new_state, 1))
            return transitions

        # Helper function to find the lexicographically smallest good caption
        def find_min_good_caption(transitions: List[Tuple[str, int]]) -> str:
            queue = [('', 0)]
            visited = set()
            while queue:
                current_state, cost = queue.pop(0)
                if (current_state, cost) not in visited:
                    visited.add((current_state, cost))
                    if len(current_state) == len(caption):
                        return current_state
                    for new_state, transition in transitions:
                        if transition == 0:
                            queue.append((current_state + new_state, cost + 1))
                        elif transition == 1:
                            queue.append((new_state + current_state, cost - 1))
            return ''

        # Main function to find the minimum cost good caption
        def find_min_cost_good_caption(caption: str) -> str:
            if len(caption) <= 2:
                return caption
            transitions = perform_transitions(caption)
            return find_min_good_caption(transitions)

        # Main function to find the minimum cost good caption
        def minCostGoodCaption(self, caption: str) -> str:
            return find_min_cost_good_caption(caption)
