class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        # Initialize max_distance to the maximum possible Manhattan distance
        max_distance = float('inf')

        # Create a dictionary to count the occurrences of each direction character
        direction_counts = {}
        for char in s:
            direction_counts[char] = direction_counts.get(char, 0) + 1

        # Count the occurrences of each direction character in the string
        for char, count in direction_counts.items():
            k -= count

        # If there are enough directions left after changing, update max_distance
        if k >= 0:
            max_distance = k

        # Iterate through the string to find the maximum distance
        for i in range(len(s)):
            # Remove the current direction character from the count
            direction_counts[s[i]] -= 1

            # Add the opposite direction character to the count
            if i + 1 < len(s):
                direction_counts[s[i + 1]] += 1

            # Count the occurrences of each direction character in the current window
            for char, count in direction_counts.items():
                if count > 0:
                    k += count

            # If there are enough directions left after adding the opposite, update max_distance
            if k >= 0:
                max_distance = max(max_distance, i + 1)

        return max_distance
