        # Starting frequency of 'a' as an odd number
        current_freq = 1 if ord('a') in char_count and char_count[ord('a')] % 2 == 1 else -1

        for i in range(len(s)):
            # Update the frequency of the current character
            if ord(s[i]) in char_count:
                current_freq += 1 if ord(s[i]) in 'abcdf' else -1

            # Check if we have found enough characters to form a substring of size k
            if i >= k:
                char = s[i - k]
                if ord(char) in char_count:
                    current_freq += 1 if ord(char) in 'abcdf' else -1

            # Update the maximum difference for the current character
            for char in 'abcdefghijklmnopqrstuvwxyz':
                if ord(char) in char_count:
                    max_diffs[char] = max(max_diffs[char], current_freq - char_count[char])

        # Return the maximum difference found or -1 if no such difference exists
        return max_diffs.values()[-1] if max_diffs.values() else -1
