class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        # Function to merge diagonals
        def merge_diagonals():
            # Priority queue to store (value, diagonal index)
            pq = []
            n = len(grid)

            # Build priority queue with (value, diagonal index)
            for i in range(n):
                for j in range(n):
                    heapq.heappush(pq, (grid[i][j], (i, j)))

            # Merge diagonals from top-right to bottom-left
            while pq:
                val, (i, j) = heapq.heappop(pq)
                if i > 0:
                    heapq.heappush(pq, (grid[i-1][j], (i-1, j)))
                if j > 0:
                    heapq.heappush(pq, (grid[i][j-1], (i, j-1)))

            # Rebuild the grid with sorted diagonals
            for i in range(n):
                for j in range(n):
                    grid[i][j] = heapq.heappop(pq)[1][1]

        # Call the merge_diagonals function
        merge_diagonals()
        return grid
