class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        # Count the frequency of each element
        element_counts = [0] * (max(elements) + 1)
        for element in elements:
            element_counts[element] += 1

        # Create a dictionary to store the order of elements
        element_order = [i for i in range(len(element_counts)) if element_counts[i] > 0]

        # Initialize the result array
        result = [-1] * len(groups)

        # Assign elements to groups
        for i, group_size in enumerate(groups):
            # Use binary search to find the first element of a group size
            index = self.binary_search(element_order, group_size)
            if index != -1:
                result[i] = element_order[index]
            else:
                result[i] = -1

        return result

    def binary_search(self, order, size):
        # Find the first element in the order that is greater than or equal to the size
        left, right = 0, len(order) - 1
        while left <= right:
            mid = left + (right - left) // 2
            if order[mid] >= size:
                right = mid - 1
            else:
                left = mid + 1
        return left if left < len(order) and order[left] >= size else -1
