from collections import defaultdict

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        # Create a dictionary for memoization
        memo = defaultdict(int)

        def dfs(i, j):
            # Base case: if we reach the end of both strings
            if i == len(s) and j == len(p):
                return 0

            # If we have already computed the result for this substring, return it
            if (i, j) in memo:
                return memo[(i, j)]

            # If we reach the end of s without finding a match, return -1
            if i == len(s):
                return -1

            # If we reach the end of p without finding a match, return the length of s minus the current index
            if j == len(p):
                return len(s) - i

            # If the current character in p is a wildcard '*', we have two options: match or do nothing
            if p[j] == '*':
                # Match the current character in s with the wildcard in p
                if s[i] == p[j] or s[i] == '*':
                    # Choose the minimum length between matching or skipping the current character in s
                    res = min(dfs(i + 1, j), dfs(i, j + 1) + 1)
                else:
                    # If the current character in s does not match the wildcard in p, skip the current character in s
                    res = dfs(i + 1, j)
            # If the current character in p is not a wildcard, match it with the current character in s
            else:
                if s[i] == p[j]:
                    res = dfs(i + 1, j + 1)
                else:
                    res = dfs(i + 1, j)

            # Store the result in memo
            memo[(i, j)] = res
            return res

        # Start the DFS from the beginning of both strings
        return dfs(0, 0)
