        max_sum = 0

        # Function to calculate the sum of elements within limits from a row
        def sumWithinLimits(row: List[int], limits: int) -> int:
            sum_limit = 0
            count = 0
            for num in row:
                if limits == count:
                    break
                if num <= limits:
                    sum_limit += num
                    count += 1
            return sum_limit

        # Iterate through each row
        for i in range(m):
            row_sum = sumWithinLimits(grid[i], limits[i])
            max_sum = max(max_sum, row_sum)

        # Calculate the sum for the remaining elements after filling a row
        for i in range(k):
            for j in range(n):
                row_sum = sumWithinLimits(grid[i], limits[i])
                max_sum += grid[i][j]
                grid[i][j] = 0  # Mark as taken
            for j in range(n):
                row_sum = sumWithinLimits(grid[i], limits[i])
                max_sum = max(max_sum, row_sum)

        return max_sum
