class Solution:
    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        n, m = len(grid), len(grid[0])
        max_sum = 0

        for row in range(n):
            for col in range(m):
                # Consider elements from the current row
                cur_sum = grid[row][col]
                taken = 1

                for i in range(row, n):
                    taken += 1
                    if taken > limits[row]:
                        break

                for j in range(col, m):
                    taken += 1
                    if taken > limits[i]:
                        break

                # Add the current element to the sum
                max_sum = max(max_sum, cur_sum + taken - 1)

                # Subtract the element from the sum for the next row
                cur_sum -= grid[row][col]

