        self.val = val
        self.left = left
        self.right = right

def max_of_two(a, b):
    return max(a, b)

def max_of_three(a, b, c):
    return max(a, b, c)

def min_cost(nums):
    if len(nums) < 3:
        return max(nums)
    root = Node(max_of_three(nums[0], nums[1], nums[2]))
    queue = [root]
    while queue:
        node = queue.pop(0)
        if node.left is not None:
            queue.append(node.left)
        if node.right is not None:
            queue.append(node.right)
        if len(queue) < 3:
            break
        node.val = max_of_three(node.left.val, node.right.val, node.val)
    return sum(nums)

