class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        def generate_permutations(current, remaining, target):
            if remaining == 0:
                if current == target:
                    return True
                return False
            for i in range(1, n + 1):
                if i not in current:
                    if generate_permutations(current + [i], remaining - 1, target):
                        return True
            return False

        def get_kth_permutation(k):
            current = []
            remaining = len(set(range(1, n + 1)))
            permutation = []
            while remaining > 0:
                if generate_permutations(current, remaining - 1, k - remaining + 1):
                    permutation.append(current + [i for i in range(1, n + 1) if i not in current])
                    break
                if not current:
                    break
                current = current + [i for i in range(1, n + 1) if i not in current][::-1]
                remaining -= 1
            if not permutation:
                return []
            permutation.sort()
            return permutation[0]

        return get_kth_permutation(k)
