        def backtrack(start=1, path=[]):
            if len(path) == n:
                if path[0] % 2 == 0:
                    path = path[1:]  # Remove the first even number
                if path[-1] % 2 == 0:
                    path = path[:-1]  # Remove the last even number
                if path[0] % 2 == 1:
                    path = path[1:]  # Remove the first odd number
                if path[-1] % 2 == 1:
                    path = path[:-1]  # Remove the last odd number
                if path[0] == 1 and path[-1] == n:
                    result.append(path)
