                if i % 2 == 0 and path[0] % 2 == 0:
                    continue
                if i % 2 == 1 and path[-1] % 2 == 1:
                    continue
                backtrack(start=i + 1, path=path + [i])

        result = []
        backtrack()
        return result[k - 1] if k <= len(result) else []
