import math

class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        length = len(s)
        dp = [[0] * length for _ in range(length)]

        # Initialize dp table for single characters
        for i in range(length):
            dp[i][i] = 1

        # Fill dp table for substrings
        for length in range(2, length + 1):
            for i in range(length - 1):
                j = i + length - 1
                if s[i] == s[j]:
                    dp[i][j] = dp[i + 1][j - 1] + 2
                else:
                    dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

        # Calculate the maximum subsequence length using binary search
        def canFormPalindrome(mid):
            operations = 0
            for i in range(length):
                if dp[i][i + mid - 1] > mid:
                    operations += 1
                if operations > k:
                    return False
            return True

        left, right = 0, length
        while left < right:
            mid = (left + right + 1) // 2
            if canFormPalindrome(mid):
                left = mid
            else:
                right = mid - 1

        return left
