        if length <= 0:
            return 0
        elif start > end:
            return -float('inf')
        elif start + length > end:
            return self.cumulative_max[end - 1] - self.cumulative_max[start - 1]
        else:
            return self.cumulative_max[start + length - 1] - self.cumulative_max[start - 1]

    def dfs(self, start, end, length):
        if end - start + 1 < m:
            return float('-inf')
        elif end - start + 1 == m:
            return self.get_max_subarray_sum(start, end, m)

        idx = self.get_idx(start, end)
        if idx - start < length:
            return self.dfs(start, idx, length)
        elif end - idx < length:
            return self.dfs(idx + 1, end, length)
        else:
            return self.get_max_subarray_sum(start, idx, length) + self.get_max_subarray_sum(idx + 1, end, length)

    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        max_sum = 0
        for i in range(k):
            max_sum += self.dfs(0, self.n, m)
        return max_sum
