            # Check if the current character in str1 matches the character at index in str2
            if str1[index] == str2[index]:
                return True
            else:
                return False

        def generate(i, j, length):
            # Helper function to generate the string recursively
            if i >= len(str1) or j >= len(str2) or i + length >= len(str1):
                return ""

            if i + length >= len(str1):
                return ""

            # Check if the current word is valid
            if is_valid(i):
                # If not, try to generate the word by swapping the characters
                for k in range(i, i + length):
                    if str1[k] == 'T':
                        for l in range(j, j + length):
                            if str2[l] != 'T':
                                return generate(i, l, length) + str1[k]
                    else:
                        for l in range(j, j + length):
                            if str2[l] == 'T':
                                return generate(i, l, length) + str1[k]
            else:
                # If it is valid, append the character from str2 to the current word
                return generate(i, j, length) + str2[j]

        # Convert str1 to a list of characters for easier manipulation
        str1 = list(str1)

        # Try to generate the word starting from the beginning of str1
        word = generate(0, 0, len(str1))

        # Convert the list back to a string
