        i = 0
        for capacity in baskets:
            # Place fruits in the leftmost available basket
            while i < len(fruits) and fruits[i] <= capacity:
                if fruits[i] > 0:
                    capacity -= fruits[i]
                    fruits[i] = 0
                i += 1
            # If no fruit can be placed in the current basket, increment remaining
            if i < len(fruits):
                remaining += 1

        return remaining
