                key = match.group(1)
                return replacements_map.get(key, match.group(0))
            return re.sub(r'%([a-z0-9])%', replace_placeholder, text)

        # Process the text
        processed_text = preprocess_text(text)

        # Replace remaining placeholders in the processed text
