class Solution:
    def longestSpecialPath(self, edges, nums):
        # Build the graph
        graph = defaultdict(list)
        for u, v, l in edges:
            graph[u].append((v, l))
            graph[v].append((u, l))

        # Initialize the queue with the root node
        queue = deque([(0, 1, False)])  # (node, length, is_special)
        visited = {0}
        longest_path = [0, 0]

        while queue:
            node, length, is_special = queue.popleft()

            # If we've reached a special node, update longest path
            if is_special:
                longest_path = max(longest_path, [length, len(nums) - 1])

            # Explore neighbors
            for neighbor, cost in graph[node]:
                if neighbor in visited:
                    continue
                if nums[neighbor] != nums[node]:
                    visited.add(neighbor)
                    queue.append((neighbor, length + cost, False))
                elif nums[neighbor] == nums[node] and length > 1:
                    visited.add(neighbor)
                    queue.append((neighbor, length + cost, True))

        return longest_path
