class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)

        # Initialize a list to store the closest index for each number
        closest_indices = [-1] * n

        # Find the closest index for each number
        for i in range(n):
            closest_indices[i] = self.findClosest(nums, i)

        # Initialize the result list with -1
        result = [-1] * len(queries)

        # Process each query
        for i, q in enumerate(queries):
            # Calculate the index of the query value
            query_index = self.findClosest(nums, q)

            # Calculate the distance if the query value exists in the array
            if query_index >= 0:
                # If the query index is the same as the closest index, return -1
                if query_index == closest_indices[query_index]:
                    result[i] = -1
                else:
                    result[i] = abs(query_index - closest_indices[query_index])
            else:
                # If the query value is not found in the array, return -1
                result[i] = -1

        return result

    def findClosest(self, nums: List[int], target: int) -> int:
        n = len(nums)
        left = 0
        right = n - 1

        while left <= right:
            mid = (left + right) // 2

            if nums[mid] == target:
                return mid
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1

        # Return the left index if the target is not found
        return left
