        # Convert properties to a set for O(1) lookups
        prop_set = set(map(tuple, properties))
        n = len(properties)

        # Mark all indices of properties[j] as already visited
        visited = [False] * n

        def dfs(i):
            if visited[i]:
                return 0
            visited[i] = True
            # Increment counter if current index is k away from properties[i]
            if i < n - 1 and properties[i][1] - properties[i][0] == k - 1:
                return 1 + dfs(i + 1)
            # Otherwise, if properties[i] and properties[j] intersect, increment counter
            elif intersect(properties[i], properties[j]):
                return 1 + dfs(j)
            return 0

        # Start DFS from each index in properties
        return sum(dfs(i) for i in range(n))

