class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        # Calculate the total number of operations needed without any subarrays
        total_operations = 0
        for num in nums:
            total_operations += abs(num) - x

        # If the total operations needed without any subarrays is less than k, return -1
        if total_operations < k:
            return -1

        # If k is 1 or the total operations needed is 0, return the total operations
        if k == 1 or total_operations == 0:
            return total_operations

        # Initialize the left and right pointers and the current sum
        left, right = 0, 0
        current_sum = 0

        # Use a sliding window approach to find the minimum number of operations
        while right < len(nums):
            current_sum += nums[right]
            while left <= right and current_sum > x * k:
                current_sum -= nums[left]
                left += 1
            if current_sum == x * k:
                return min(total_operations, right - left + 1)
            right += 1

        return -1
