        # Calculate the total number of elements needed to be equalized to x
        total_elements = len(nums) // k * x

        # If total_elements is less than x, it's impossible to achieve with k operations
        if total_elements < x:
            return -1

        # Initialize variables
        left = 0
        right = len(nums) - 1
        operations = float('inf')
        current_sum = 0

        # Binary search to find the minimum number of operations
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == x:
                # Check if we can get enough elements by moving left
                if total_elements - current_sum >= x:
                    operations = min(operations, mid - left)
                    right = mid - 1
                else:
                    left = mid + 1
            elif nums[mid] > x:
                current_sum += mid - left
                if total_elements - current_sum >= x:
                    operations = min(operations, mid - left + 1)
                    left = mid + 1
                else:
                    left = mid + 1
            else:
                # Ensure we have at least x elements
                if total_elements - current_sum >= x:
                    operations = min(operations, right - mid)
                    right = mid - 1
                else:
                    current_sum += mid - left
                    right = mid - 1

        # If no valid subarray is found, return -1
        return operations if operations != float('inf') else -1
